    const peers=fighters.filter(f=>f.team===fighter.team&&!f.koScored).sort((a,b)=>Math.hypot(a.x-ball.x,a.y-ball.y)-Math.hypot(b.x-ball.x,b.y-ball.y)||a.playerIndex-b.playerIndex),rank=peers.indexOf(fighter);
