    const plan=ai.fieldGoalPlan;if(!plan)return aiButtonsToInput(ai,toward);
    let destination=guarding?{x:standX,y:perch.y-fighter.data.height/2}:available?{...plan.approach}:{x:team===0?stage.width*.35:stage.width*.65,y:stage.floorY-fighter.data.height/2};
    if(guarding&&threat&&distance<500)destination={x:ball.x,y:ball.y};
    if(court)destination.x=team===0?Math.min(destination.x,stage.width/2-fighter.data.width/2-3):Math.max(destination.x,stage.width/2+fighter.data.width/2+3);
    const reach=fighter.data.punchReach+fighter.data.punchRadius+60,danger=Boolean(threat)&&ball.launched>0&&distance<reach+60;
    const enemy=!court&&guarding?fighters.filter(f=>f.team!==team&&!f.koScored&&Math.hypot(f.x-fighter.x,f.y-fighter.y)<145).sort((a,b)=>a.playerIndex-b.playerIndex)[0]:null;
    if(enemy&&ai.punchCooldown<=0&&!fighter.attack){startAiPunch(ai,normalize({x:enemy.x-fighter.x,y:enemy.y-fighter.y}),.14,.35);return aiButtonsToInput(ai,ai.aim);}
    if(!fighter.attack&&ai.punchCooldown<=0&&(danger||ball.carrier===fighter.id||available&&!guarding&&distance<reach&&dot(toward,plan.aim)>.25&&!plan.kick)){
      startAiPunch(ai,danger?toward:plan.aim,danger?.12:Math.max(.05,fighter.data.punchChargeTime*plan.charge),.25);return aiButtonsToInput(ai,ai.aim);
    }
