  function updateFighterInput(fighter, dt) {
    if(fighter.koScored||fighter.hitstun>0||fighter.hitstop>0||fighter.juked>0||fighter.punchBlockstun>0||
       fighter.spotDodgeRecovery>0||fighter.surfaceTechTravelTimer>0)resetGroundRun(fighter,true);
    if(isUpperRecovering(fighter))return;
    if (fighter.koScored) {
      fighter.hasLiveAim = false;
      fighter.punchInputHeld = false;
      fighter.tippyToes = false;
      fighter.tippyToesHold = 0;
      fighter.crouching = false;
      clearPendingActions(fighter);
      return;
    }

    let input = !simulationInputActive && isAiEnabled(fighter) ? readAiInput(fighter, dt) : readInput(fighter);
    if(matchSession){
      const locks=matchSession.releaseLocks[fighter.id]||{dash:true,punch:true,down:true};
      const blocked=["dash","punch","down"].filter(action=>locks[action]);
      input=MatchFlow.gate(matchSession,fighter.id,input);
      for(const action of blocked){
        consumeInputBuffer(fighter,`${action}Pressed`);consumeInputBuffer(fighter,`${action}Released`);
      }
    }
    fighter.platformPassHeld = input.downHeld && input.dashHeld && fighter.hitstun <= 0 && fighter.juked <= 0;
    fighter.hasLiveAim = input.hasAim;
    fighter.punchInputHeld = input.punchHeld;
    if(fighter.data.boomerang&&input.punchHeld&&hasActiveBoomerang(fighter))fighter.boomerangRecallRelease=true;

    if (fighter.airBrakeOnly && (fighter.onGround || fighter.wallSliding)) {
      stopAirBrakeOnly(fighter);
    }

    if (input.hasAim) {
      fighter.aim = input.aim;
      fighter.face = input.aim;
    }

    if(isPhantomGhost(fighter)){
      if(input.dashPressed&&fighter.hitstop<=0&&roundResetTimer<=0)endPhantomDash(fighter,input.hasAim?input.aim:fighter.phantomDash.dir);
      clearPendingActions(fighter);fighter.attack=null;fighter.punchVisual=null;fighter.phantomPunchLock=true;
      for(const name of ["dashPressed","dashReleased","punchPressed","punchReleased","downPressed"])consumeInputBuffer(fighter,name);
      fighter.punchInputHeld=false;return;
    }
    if(fighter.data.phantomDash&&fighter.phantomPunchLock){
      if(!input.punchHeld)fighter.phantomPunchLock=false;
      input={...input,punchHeld:false,punchPressed:false,punchReleased:false};fighter.punchInputHeld=false;
      consumeInputBuffer(fighter,"punchPressed");consumeInputBuffer(fighter,"punchReleased");
    }

    // Discard pressure-time edges, even during hitstop. Observe a held Punch
    // after recovery before accepting a fresh release as a shield parry.
    if (fighter.punchBlockstun > 0 || fighter.shieldPressureRearm) {
      for (const name of ["dashPressed", "dashReleased", "punchPressed", "punchReleased", "downPressed"]) {
        consumeInputBuffer(fighter, name);
      }
      fighter.shieldReleaseParry = 0;
      fighter.punchReleaseQueued = false;
      fighter.platformPassHeld = false;
      fighter.dashPending = false;
      fighter.chargingDash = false;
      fighter.airBrakeOnly = false;
      fighter.crouching = false;
      fighter.tippyToes = false;
      fighter.tippyToesHold = 0;
      fighter.spotDodgeDownTapWindow = 0;
      updatePunchAim(fighter, input.aim, input.hasAim, dt);
      if (fighter.punchBlockstun <= 0) {
        fighter.shieldPressureRearm = false;
        if (!input.punchHeld) clearPendingActions(fighter);
      }
      return;
    }

    if (fighter.hitstop > 0 || roundResetTimer > 0) {
      return;
    }

    if (fighter.juked > 0 || fighter.spotDodgeRecovery > 0) {
      fighter.shieldHeldTimer = 0;
      clearPendingActions(fighter);
      fighter.tippyToes = false;
      fighter.crouching = fighter.forceCrouch > 0 || fighter.spotDodgeRecovery > 0;
      return;
    }

    if (fighter.hitstun > 0) {
      const predictedSurface = getSurfaceTechPrediction(fighter, TECH_HOLD_ASSIST_WINDOW);
      const heldFloorTechIntent =
        input.dashHeld &&
        input.downHeld &&
        predictedSurface?.surface === "floor" &&
        fighter.floorTechReady <= 0 &&
        predictedSurface.time <= TECH_HOLD_ASSIST_WINDOW;
      if (input.dashPressed || heldFloorTechIntent) {
        const queuedTech = queueSurfaceTech(fighter, input.aim);
        if (!queuedTech && input.dashPressed) {
          if (fighter.escapeWindow > 0) {
            tryComboEscape(fighter, input.aim);
          } else {
            bufferComboEscape(fighter, input.aim);
          }
        }
        if (input.dashPressed) {
          consumeInputBuffer(fighter, "dashPressed");
        }
      }
      if (input.punchPressed) {
        tryHitstunPunchParry(fighter);
        consumeInputBuffer(fighter, "punchPressed");
      }
      clearPendingActions(fighter);
      fighter.tippyToes = false;
      fighter.crouching = false;
      return;
    }

    const shielding = isShielding(fighter);
    fighter.shieldHeldTimer = shielding ? fighter.shieldHeldTimer + dt : 0;
    const shieldSettled = fighter.shieldHeldTimer >= SPOT_DODGE_SHIELD_SETTLE_TIME;
    if (shielding && !shieldSettled && input.downPressed) {
      consumeInputBuffer(fighter, "downPressed");
      fighter.spotDodgeDownTapWindow = 0;
    }
    if (!shielding) {
      fighter.spotDodgeDownTapWindow = 0;
    }
    if (
      shielding &&
      shieldSettled &&
      input.downPressed &&
      fighter.spotDodgeInvuln <= 0 &&
      fighter.spotDodgeRecovery <= 0
    ) {
      consumeInputBuffer(fighter, "downPressed");
      if (fighter.spotDodgeDownTapWindow > 0) {
        startSpotDodge(fighter);
        return;
      }
      fighter.spotDodgeDownTapWindow = SPOT_DODGE_DOUBLE_TAP_WINDOW;
      fighter.spotDodgeFlash = Math.max(fighter.spotDodgeFlash, 0.08);
    }

    if (input.dashHeld && input.downHeld && canDropThroughPlatform(fighter)) {
      consumeInputBuffer(fighter, "dashPressed");
      performPlatformDrop(fighter);
      return;
    }

    const canDashNow = (fighter.onGround || !fighter.data.phantomDash&&fighter.wallSliding || fighter.airDashes > 0) && !fighter.heavyDashWindup && !(fighter.heavyDashRecovery>0);
    const canStartAirBrakeOnly = !fighter.data.phantomDash&&!fighter.onGround && !fighter.wallSliding && fighter.airDashes <= 0;
    if (input.dashPressed && canStartAirBrakeOnly) {
      consumeInputBuffer(fighter, "dashPressed");
      fighter.airBrakeOnly = true;
      fighter.dashChargeAge = 0;
      fighter.fullDashChargeHold = 0;
      fighter.airSteerTimer = 0;
      fighter.airSteerDuration = 0;
      fighter.airSteerSpeed = 0;
    } else if (input.dashPressed && canDashNow) {
      consumeInputBuffer(fighter, "dashPressed");
      fighter.dashPending = true;
      fighter.tippyDashQueued = fighter.tippyToes && fighter.onGround && !fighter.wallSliding;
      fighter.dashHoldTimer = 0;
      fighter.dashCharge = 0;
      fighter.dashChargeAge = 0;
      fighter.fullDashChargeHold = 0;
    }

    if (fighter.airBrakeOnly) {
      if (input.dashHeld) {
        fighter.dashChargeAge += dt;
      }
      if (input.dashReleased || !input.dashHeld) {
        if (input.dashReleased) {
          consumeInputBuffer(fighter, "dashReleased");
        }
        stopAirBrakeOnly(fighter);
      }
    }

    if (fighter.dashPending && input.dashHeld) {
      fighter.dashHoldTimer += dt;
      if (!fighter.chargingDash && fighter.dashHoldTimer >= DASH_TAP_GRACE) {
        enterDashCharge(fighter);
      }
    }
    if (fighter.chargingDash && input.dashHeld) {
      const previousCharge = fighter.dashCharge;
      fighter.dashCharge = Math.min(fighter.data.dashChargeTime, fighter.dashCharge + dt);
      playDashChargeAudio(fighter, previousCharge, fighter.dashCharge);
      fighter.dashChargeAge += dt;
      fighter.fullDashChargeHold =
        fighter.dashCharge >= fighter.data.dashChargeTime ? fighter.fullDashChargeHold + dt : 0;
    }
    if (fighter.dashPending && input.dashReleased) {
      consumeInputBuffer(fighter, "dashReleased");
      releaseDash(fighter, input.aim, fighter.chargingDash ? fighter.dashCharge : 0);
    } else if (fighter.dashPending && !input.dashHeld) {
      releaseDash(fighter, input.aim, fighter.chargingDash ? fighter.dashCharge : 0);
    }

    if(fighter.data.punchSequence&&!fighter.data.automaticSequence&&input.punchPressed&&!fighter.punchPending){
      const chain=fighter.edgebertChain;
      const eligible=chain&&chain.stage<2&&chain.age>=chain.cancelAt-EDGEBERT_SEQUENCE_BUFFER&&chain.age<=chain.total+EDGEBERT_SEQUENCE_GRACE;
      fighter.edgebertFollowup=eligible?chain.stage+1:null;
      if(chain&&!eligible&&fighter.attack)consumeInputBuffer(fighter,"punchPressed");
    }
    const canChargePunch = (!fighter.attack || fighter.edgebertFollowup != null) && !fighter.heavyDashWindup;
    const sequenceReady=fighter.edgebertFollowup==null||!fighter.edgebertChain||fighter.edgebertChain.age>=fighter.edgebertChain.cancelAt;
    const canFirePunch = canChargePunch && sequenceReady && fighter.whiffLag <= 0 && fighter.punchLockout <= 0;
    if (!canChargePunch && (fighter.punchPending || fighter.chargingPunch)) {
      fighter.punchPending = false;
      fighter.punchReleaseQueued = false;
      fighter.punchHoldTimer = 0;
      fighter.punchCharge = 0;
      fighter.chargingPunch = false;
      fighter.punchAimSamples = [];
    }

    if (canChargePunch && !fighter.punchPending && (input.punchPressed || input.punchHeld)) {
      consumeInputBuffer(fighter, "punchPressed");
      fighter.punchPending = true;
      fighter.punchReleaseQueued = false;
      fighter.punchExhausted = false;
      fighter.punchHoldTimer = 0;
      fighter.punchCharge = 0;
      fighter.shieldActiveTime = 0;
      beginPunchAim(fighter, input.hasAim ? input.aim : fighter.face);
    }

    if (fighter.punchPending && !fighter.punchReleaseQueued) {
      updatePunchAim(fighter, input.aim, input.hasAim, dt);
    }
    if (fighter.punchPending && input.punchHeld) {
      fighter.punchReleaseQueued = false;
      fighter.punchHoldTimer += dt;
      if (!fighter.chargingPunch && fighter.punchHoldTimer >= PUNCH_TAP_GRACE) {
        fighter.chargingPunch = true;
        fighter.punchCharge = 0;
      }
    }
    if (fighter.chargingPunch && input.punchHeld) {
      if (!fighter.punchExhausted) {
        fighter.punchCharge = Math.min(fighter.data.punchChargeTime, fighter.punchCharge + dt);
      }
    }
    if (fighter.punchPending && input.punchReleased) {
      consumeInputBuffer(fighter, "punchReleased");
      if (canFirePunch || fighter.data.boomerang&&fighter.boomerangRecallRelease) {
        releasePunch(fighter, fighter.punchAim, fighter.punchCharge);
      } else {
        fighter.punchReleaseQueued = true;
      }
    } else if (fighter.punchPending && !input.punchHeld) {
      fighter.punchReleaseQueued = true;
    }
    if (fighter.punchReleaseQueued && (canFirePunch || fighter.data.boomerang&&fighter.boomerangRecallRelease)) {
      releasePunch(fighter, fighter.punchAim, fighter.punchCharge);
    }

    const canGroundCrouch =
      fighter.onGround &&
      input.hasAim &&
      !fighter.dashPending &&
      !fighter.chargingDash &&
      !fighter.attack &&
      fighter.whiffLag <= 0;
    const canGroundTippy =
      fighter.onGround &&
      input.hasAim &&
      !fighter.attack &&
      fighter.whiffLag <= 0 &&
      !fighter.punchPending &&
      !fighter.chargingPunch &&
      fighter.punchLockout <= 0;
    fighter.crouching = canGroundCrouch && (stageGravityAxis === "x"
      ? input.aim.x * stageGravitySign > TIPPY_TOES_INPUT_DOT
      : stageGravitySign > 0 ? input.downHeld : input.upHeld);
    const holdingTippyIntent =
      canGroundTippy && input.hasAim && dot(input.aim, gravityVector()) < -TIPPY_TOES_INPUT_DOT && !fighter.crouching;
    fighter.tippyToesHold = holdingTippyIntent ? fighter.tippyToesHold + dt : 0;
    fighter.tippyToes = fighter.tippyToesHold >= TIPPY_TOES_HOLD_TIME;
    if (fighter.dashPending || fighter.chargingDash) {
      fighter.tippyDashQueued = fighter.tippyToes && fighter.onGround && !fighter.wallSliding;
    }
  }

  function enterDashCharge(fighter) {
    fighter.chargingDash = true;
    fighter.dashChargeAirborne = !fighter.onGround && !fighter.wallSliding;
    fighter.dashCharge = 0;
    fighter.dashChargeAge = 0;
    fighter.fullDashChargeHold = 0;
    if (fighter.dashChargeAirborne) {
      fighter.airSteerTimer = 0;
      fighter.airSteerDuration = 0;
      fighter.airSteerSpeed = 0;
    }
  }

  function stopAirBrakeOnly(fighter) {
    fighter.airBrakeOnly = false;
    fighter.dashChargeAge = 0;
    fighter.fullDashChargeHold = 0;
  }

  function clearPendingActions(fighter) {
    if(fighter.data.boomerang)delete fighter.heavyDashWindup;
    resetPunchSequence(fighter);
    fighter.punchExhausted = false;
    fighter.punchReleaseQueued = false;
    fighter.dashPending = false;
    fighter.dashHoldTimer = 0;
    fighter.chargingDash = false;
    fighter.dashChargeAirborne = false;
    fighter.airBrakeOnly = false;
    fighter.dashCharge = 0;
    fighter.dashChargeAge = 0;
    fighter.fullDashChargeHold = 0;
    fighter.punchPending = false;
    fighter.punchHoldTimer = 0;
    fighter.chargingPunch = false;
    fighter.punchCharge = 0;
    fighter.tippyToes = false;
    fighter.tippyToesHold = 0;
    fighter.tippyDashQueued = false;
    fighter.shieldReleaseParry = 0;
    fighter.shieldReleaseWhiffFlash = 0;
    fighter.shieldParrySuccessFlash = 0;
    fighter.shieldHeldTimer = 0;
    fighter.spotDodgeDownTapWindow = 0;
    clearShieldDashLockout(fighter);
  }

  function tryHitstunPunchParry(fighter) {
    if (!canUseParryCommand(fighter) || !fighter.punchParryAvailable) {
      return;
    }

    spendDefensiveResource(fighter, "punch");
    fighter.hitstunParryActive = HITSTUN_PARRY_WINDOW;
    fighter.hitstunParryFlash = 0.18;
    fighter.hitstunParryMissPending = true;
    fighter.resourceFlash = 0.18;
    sparkText(fighter.x, fighter.y - 66, "PARRY?", fighter.data.lightColor);
  }

  function startSpotDodge(fighter) {
    resetPunchSequence(fighter);
    fighter.spotDodgeInvuln = SPOT_DODGE_INVULN;
    fighter.spotDodgeRecovery = 0;
    fighter.spotDodgeAvoided = false;
    fighter.spotDodgePendingWhiff = true;
    fighter.spotDodgeFlash = Math.max(fighter.spotDodgeFlash, SPOT_DODGE_INVULN);
    fighter.invulnerable = Math.max(fighter.invulnerable, SPOT_DODGE_INVULN);
    fighter.forceCrouch = Math.max(fighter.forceCrouch, SPOT_DODGE_INVULN + SPOT_DODGE_WHIFF_RECOVERY);
    fighter.crouching = true;
    fighter.punchPending = false;
    fighter.punchHoldTimer = 0;
    fighter.chargingPunch = false;
    fighter.punchCharge = 0;
    fighter.shieldHeldTimer = 0;
    fighter.spotDodgeDownTapWindow = 0;
    fighter.shieldReleaseParry = 0;
    fighter.shieldReleaseWhiffFlash = 0;
    clearShieldDashLockout(fighter);
    fighter.vx *= 0.35;
    fighter.vy *= 0.7;
    burst(fighter.x, fighter.y + fighter.data.height * 0.18, 10, fighter.data.lightColor, 3);
  }

  function canDropThroughPlatform(fighter) {
    return (
      fighter.onGround &&
      fighter.onPassThroughPlatform &&
      fighter.groundTerrainId &&
      fighter.hitstun <= 0 &&
      fighter.hitstop <= 0 &&
      fighter.juked <= 0 &&
      fighter.spotDodgeInvuln <= 0 &&
      fighter.spotDodgeRecovery <= 0 &&
      roundResetTimer <= 0
    );
  }

  function performPlatformDrop(fighter) {
    fighter.platformDropTimer = PLATFORM_DROP_TIME;
    fighter.platformDropPlatformId = fighter.groundTerrainId;
    fighter.onGround = false;
    fighter.onPassThroughPlatform = false;
    fighter.groundTerrainId = null;
    fighter.groundSkidTimer = 0;
    fighter.dashPending = false;
    fighter.chargingDash = false;
    fighter.dashChargeAirborne = false;
    fighter.airBrakeOnly = false;
    fighter.dashHoldTimer = 0;
    fighter.dashCharge = 0;
    fighter.dashChargeAge = 0;
    fighter.fullDashChargeHold = 0;
    fighter.forceCrouch = Math.max(fighter.forceCrouch, 0.08);
    fighter.tippyToes = false;
    fighter.tippyToesHold = 0;
    fighter.crouching = true;
    fighter.y += PLATFORM_DROP_NUDGE;
    fighter.vy = Math.max(fighter.vy, PLATFORM_DROP_SPEED);
    fighter.flash = Math.max(fighter.flash, 0.08);
    burst(fighter.x, fighter.y - fighter.data.height * 0.35, 8, fighter.data.lightColor, 2.5);
    sparkText(fighter.x, fighter.y - 58, "DROP", fighter.data.lightColor);
  }

  function aiButtonsToInput(ai,aim,consume=true) {
    const input={aim,hasAim:true,upHeld:false,downHeld:false,downPressed:false,
      dashHeld:ai.dashHeld,punchHeld:ai.punchHeld,
      dashPressed:consume&&ai.dashPressQueued,dashReleased:consume&&ai.dashReleaseQueued,
      punchPressed:consume&&ai.punchPressQueued,punchReleased:consume&&ai.punchReleaseQueued};
    if(consume) {ai.dashPressQueued=false;ai.dashReleaseQueued=false;ai.punchPressQueued=false;ai.punchReleaseQueued=false;}
    return input;
  }

  function readBoomerangusAi(fighter,dt){
    const ai=fighter.ai,stage=currentStage(),gravity=gravityVector();
    ai.dashCooldown=Math.max(0,ai.dashCooldown-dt);ai.punchCooldown=Math.max(0,ai.punchCooldown-dt);
    tickAiButton(ai,"dash",dt);tickAiButton(ai,"punch",dt);
    if(!ai.boomerangPost)ai.boomerangPost={x:fighter.x,y:fighter.y};
    let objective=chooseAiOpponent(fighter),post={...ai.boomerangPost},sports=false;
    if(dashballState){
      sports=true;const objects=Dashball.balls(dashballState),own=objects.filter(b=>!b.carrier||b.carrier===fighter.id);
      objective=dashballState.targetCharge?own.find(b=>b.scoringTeam===fighter.team):own.sort((a,b)=>Math.hypot(a.x-fighter.x,a.y-fighter.y)-Math.hypot(b.x-fighter.x,b.y-fighter.y))[0];
      post={x:fighter.team?stage.width-520:520,y:gravity.y<0?24+fighter.data.height/2:stage.floorY-fighter.data.height/2};
      if(dashballState.targetCharge&&objective){
        const goal=dashballState.targetCharge.target,dx=objective.x-goal.x;
        post.x=clamp(objective.x+(Math.sign(dx)||(fighter.team?1:-1))*300,fighter.team?stage.width*.52:100,fighter.team?stage.width-100:stage.width*.48);
      }else if(dashballState.boulder&&objective)post.x=fighter.team?stage.width*.72:stage.width*.28;
    }else if(sandbagState){sports=true;objective=sandbagState.bags.find(b=>b.team===null||b.team===fighter.team);}
    if(!objective)return aiButtonsToInput(ai,fighter.face);
    const offset=shortestOffset(fighter,objective),distance=Math.max(0,length(offset)-(objective.r||0));
    const lead=clamp(distance/1000,0,.45),aim=normalize({x:offset.x+(objective.vx||0)*lead,y:offset.y+(objective.vy||0)*lead});
    const active=fighters.flatMap(f=>f.projectiles).find(a=>a.projectile.boomerang&&!a.projectile.removed&&(a.projectile.creatorId===fighter.id||a.reflectedOwnerId===fighter.id));
    if(active?.projectile.boomerang.phase==="return")post.x+=clamp(offset.x,-80,80);
    if(fighter.hitstun>0||fighter.koScored||fighter.juked>0)return aiButtonsToInput(ai,aim);
    if(ai.punchHeld||ai.dashHeld||ai.punchReleaseQueued||ai.dashReleaseQueued)return aiButtonsToInput(ai,ai.aim||aim);
    if(active){
      const recall=active.projectile.boomerang,defend=distance<300;
      const fastRecovery=(getSlotIndex(fighter.id)+Math.floor(recall.flightTime*2))%3!==0;
      if(ai.punchCooldown<=0&&fighter.shieldHealth>fighter.data.shieldMax*.18&&(defend||fastRecovery))startAiPunch(ai,aim,defend?.65:1.2,defend?1:1.6);
    }else if(distance<620&&distance>(sports?15:85)&&ai.punchCooldown<=0&&!fighter.attack&&!fighter.heavyDashWindup){
      startAiPunch(ai,aim,sports ? .32 : .12,1.1);
    }
    const delta={x:post.x-fighter.x,y:post.y-fighter.y},travel=length(delta);
    if(travel>150&&ai.dashCooldown<=0&&!ai.punchHeld&&!fighter.attack&&!fighter.heavyDashWindup&&!(fighter.heavyDashRecovery>0)&&(fighter.onGround||fighter.airDashes>0))startAiDash(ai,normalize(delta),.16,1.5);
    return aiButtonsToInput(ai,ai.punchHeld||ai.dashHeld?ai.aim:aim);
  }

  function readAiInput(fighter,dt){
    const input=readStandardAiInput(fighter,dt);
    if(fighter.data.momentumShield)return readMirrorAi(fighter,input);
    if(fighter.data.booster||fighter.data.lamer)return readStatusFighterAi(fighter,input);
    if(!fighter.data.phantomDash)return input;
    if(isPhantomGhost(fighter))return {...input,punchHeld:false,punchPressed:false,punchReleased:false};
    if(!fighter.onGround&&fighter.airDashes>0){
      const objects=dashballState?Dashball.balls(dashballState).filter(b=>!dashballState.targetCharge||b.scoringTeam===fighter.team)
        :sandbagState?sandbagState.bags.filter(b=>b.team===null||b.team===fighter.team):fighters.filter(f=>f!==fighter&&!f.koScored&&isPreferredAiTarget(fighter,f));
      const target=[...objects].sort((a,b)=>length(shortestOffset(fighter,a))-length(shortestOffset(fighter,b)))[0];
      if(target){
        const delta=shortestOffset(fighter,target),distance=length(delta),range=fighter.data.phantomDash.speed*fighter.data.phantomDash.duration;
        if(distance>range*.85&&distance<range*1.2&&!input.punchHeld&&fighter.ai.dashCooldown<=0){
          const aim=normalize({x:delta.x+(target.vx||0)*.2,y:delta.y+(target.vy||0)*.2});
          startAiDash(fighter.ai,aim,.04,.9);return aiButtonsToInput(fighter.ai,aim);
        }
      }
    }
    return input;
  }

  function readMirrorAi(fighter,input){
    const ai=fighter.ai;
    if(fighter.hitstun>0||fighter.koScored||fighter.attack||fighter.chargingDash)return input;
    if(fighter.shieldHealth<fighter.data.shieldMax*.22&&input.punchHeld){
      ai.punchHeld=false;ai.punchTimer=0;ai.punchCooldown=1.2;
      return {...input,punchHeld:false,punchPressed:false,punchReleased:true};
    }
    const objects=[...fighters.filter(f=>f!==fighter&&!f.koScored&&canFightersAffect(fighter,f)),
      ...(dashballState?Dashball.balls(dashballState):sandbagState?sandbagState.bags:[])];
    const threat=objects.map(object=>{const offset=shortestOffset(fighter,object),distance=length(offset),normal=normalize(offset);
      return {object,offset,distance,closing:-dot({x:object.vx-fighter.vx,y:object.vy-fighter.vy},normal)};
    }).filter(t=>t.distance-(t.object.r||0)<330&&t.closing>80).sort((a,b)=>a.distance-b.distance)[0];
    if(threat&&fighter.shieldHealth>fighter.data.shieldMax*.3&&!fighter.punchExhausted&&!input.punchReleased){
      const aim=getAiDefensiveAim(threat.offset);
      if(input.punchHeld)return {...input,aim,hasAim:true};
      if(ai.punchCooldown<=0&&!fighter.whiffLag){
        ai.dashHeld=false;ai.dashPressQueued=ai.dashReleaseQueued=false;
        startAiPunch(ai,aim,1.2+gameplayRandom()*1.4,2.9);return aiButtonsToInput(ai,aim);
      }
    }
    return input;
  }

  function readStatusFighterAi(fighter,input){
    if(fighter.hitstun>0||fighter.koScored||fighter.attack||fighter.whiffLag>0)return input;
    const ai=fighter.ai,enemy=chooseAiOpponent(fighter),court=dashballState?.config.ruleset==="court"||sandbagState?.config.ruleset==="race";
    const ally=fighter.data.booster&&fighters.find(other=>other!==fighter&&areSameTeam(fighter,other)&&!other.koScored&&!isPhantomGhost(other)&&
      !(other.boosterEnhancement?.remaining>.5)&&(court||other.health>70&&other.health>getMatchMaxHealth(other)*.65)&&
      length(shortestOffset(fighter,other))<85);
    if(ally&&!input.dashHeld&&!input.punchHeld&&!input.punchReleased&&ai.punchCooldown<=0&&
      (simulationFrame+getSlotIndex(fighter.id)*71)%180<3&&!enemy?.attack){
      startAiPunch(ai,normalize(shortestOffset(fighter,ally)),2.5,3.5);return aiButtonsToInput(ai,ai.aim);
    }
    if(input.punchPressed&&!input.dashHeld&&!court&&!(enemy?.attack)){
      if(fighter.data.booster&&!dashballState&&!sandbagState&&enemy?.boosterEnhancement?.remaining>1&&enemy.health>25){
        ai.punchHeld=false;ai.punchTimer=0;ai.punchCooldown=.5;
        return {...input,aim:normalize(shortestOffset(enemy,fighter)),punchHeld:false,punchPressed:false,punchReleased:false};
      }
      if(!dashballState&&!sandbagState)ai.punchTimer=fighter.data.lamer?
        (enemy?.lamerSuppression?.stacks>=3||gameplayRandom()<.35?1.8+gameplayRandom()*1.25:.08):enemy?.health<30?.12:1.3+gameplayRandom()*1.8;
    }
    if(fighter.data.lamer&&input.punchPressed&&!input.dashHeld&&(dashballState||sandbagState)&&gameplayRandom()<.35)ai.punchTimer=2.4+gameplayRandom()*.6;
    return input;
  }

  function readStandardAiInput(fighter, dt) {
    if(fighter.data.boomerang)return readBoomerangusAi(fighter,dt);
    if(sandbagState)return readSandbagAi(fighter,dt);
    if(dashballState)return readDashballAi(fighter,dt);
    const ai = fighter.ai;
    const opponent = chooseAiOpponent(fighter);
    if (!opponent) {
      return {
        aim: { ...fighter.face },
        hasAim: false,
        upHeld: false,
        downHeld: false,
        downPressed: false,
        dashHeld: false,
        dashPressed: false,
        dashReleased: false,
        punchHeld: false,
        punchPressed: false,
        punchReleased: false,
      };
    }
    const threat = chooseAiThreat(fighter) || opponent;
    const toOpponent = shortestOffset(fighter, opponent);
    const physicalDistance = Math.hypot(opponent.x - fighter.x, opponent.y - fighter.y);
    const predicted = {
      x: toOpponent.x + opponent.vx * 0.12,
      y: toOpponent.y + opponent.vy * 0.08,
    };
    const directChaseAim = length(predicted) > 1 ? normalize(predicted) : { ...fighter.face };
    const route = getAiRoute(fighter, opponent, directChaseAim);
    const chaseAim = route.aim;
    const distance = route.distance;
    const awayAim = normalize({
      x: -chaseAim.x || -fighter.face.x,
      y: -chaseAim.y * 0.5 - 0.25,
    });
    const canDash = fighter.onGround || fighter.wallSliding || fighter.airDashes > 0;
    const incoming = threat !== opponent || incomingAttackDanger(opponent, fighter, physicalDistance);
    const wallAim = getAiWallAim(fighter);
    const hitstunAim = normalize({
      x: -Math.sign(toOpponent.x || fighter.lastHitDir.x || fighter.face.x || 1),
      y: fighter.vy > 120 ? -0.28 : 0.18,
    });

    ai.dashCooldown = Math.max(0, ai.dashCooldown - dt);
    ai.punchCooldown = Math.max(0, ai.punchCooldown - dt);
    ai.decisionCooldown = Math.max(0, ai.decisionCooldown - dt);
    ai.escapeCooldown = Math.max(0, ai.escapeCooldown - dt);

    tickAiButton(ai, "dash", dt);
    tickAiButton(ai, "punch", dt);

    if (fighter.chargingDash && !ai.dashHeld && !ai.dashReleaseQueued) {
      ai.dashReleaseQueued = true;
    }
    if (fighter.chargingPunch && !ai.punchHeld && !ai.punchReleaseQueued) {
      ai.punchReleaseQueued = true;
    }
    if (fighter.chargingDash && fighter.dashChargeAge > 0.72 && !ai.dashReleaseQueued) {
      ai.dashHeld = false;
      ai.dashReleaseQueued = true;
    }

    const surfaceTechAim = fighter.hitstun > 0 ? getAiSurfaceTechAim(fighter) : null;
    if (
      !ai.dashHeld &&
      !ai.dashReleaseQueued &&
      surfaceTechAim &&
      gameplayRandom() < 0.78
    ) {
      startAiDash(ai, surfaceTechAim, 0.035, 0.28);
    }

    if (!ai.dashHeld && !ai.punchHeld && !ai.dashReleaseQueued && !ai.punchReleaseQueued) {
      const comboDefenseBonus = clamp(fighter.comboHits * 0.03, 0, AI_LONG_COMBO_DEFENSE_BONUS);
      if (canUseParryCommand(fighter) && fighter.punchParryAvailable && incoming && ai.punchCooldown <= 0) {
        if (gameplayRandom() < AI_HITSTUN_PARRY_CHANCE + comboDefenseBonus * 0.65) {
          startAiPunch(ai, getAiDefensiveAim(multiply(threat.attack.dir, -1)), 0.045 + gameplayRandom() * 0.055, 1.35);
        } else {
          ai.punchCooldown = AI_DEFENSE_HESITATION_MIN + gameplayRandom() * AI_DEFENSE_HESITATION_RANDOM;
        }
      } else if (
        canUseComboBreaker(fighter) &&
        fighter.escapeAvailable &&
        (fighter.escapeWindow > 0 || incoming) &&
        ai.escapeCooldown <= 0
      ) {
        if (gameplayRandom() < AI_COMBO_ESCAPE_CHANCE + comboDefenseBonus) {
          startAiDash(ai, getAiDefensiveAim(multiply(fighter.lastHitDir, -1)), 0.04 + gameplayRandom() * 0.06, 0.48);
          ai.escapeCooldown = 1.15;
        } else {
          ai.escapeCooldown = AI_DEFENSE_HESITATION_MIN + gameplayRandom() * AI_DEFENSE_HESITATION_RANDOM;
        }
      } else if (incoming && canDash && ai.dashCooldown <= 0) {
        if (gameplayRandom() < AI_NEUTRAL_DASH_PARRY_CHANCE) {
          startAiDash(ai, awayAim, 0.03 + gameplayRandom() * 0.055, 0.46);
        } else {
          ai.dashCooldown = AI_DEFENSE_HESITATION_MIN + gameplayRandom() * AI_DEFENSE_HESITATION_RANDOM;
        }
      } else if (fighter.hitstun <= 0 && ai.decisionCooldown <= 0) {
        if (wallAim && canDash && fighter.airDashes <= 1 && !fighter.wallSliding && ai.dashCooldown <= 0 && gameplayRandom() < 0.35) {
          startAiDash(ai, wallAim, 0.04, 0.4);
        } else if (route.requiresMovement && canDash && ai.dashCooldown <= 0) {
          const hold = clamp((distance - 70) / 850, 0.08, 0.3);
          startAiDash(ai, chaseAim, hold, 0.18 + gameplayRandom() * 0.1);
        } else if (distance < 74 && canDash && ai.dashCooldown <= 0 && gameplayRandom() < 0.45) {
          startAiDash(ai, awayAim, 0.06, 0.42);
        } else if (!route.blocker && !route.usesWrap && distance < aiPunchRange(fighter) && ai.punchCooldown <= 0) {
          const shot = fighter.data.projectileConfig;
          const hold = shot ? shot.aiHold : distance < 82 ? 0.055 : 0.12 + gameplayRandom() * 0.12;
          startAiPunch(ai, chaseAim, hold, shot ? shot.aiCooldown : 0.34);
        } else if (canDash && distance > 130 && ai.dashCooldown <= 0) {
          const verticalNudge = fighter.y > opponent.y + 55 ? -0.28 : fighter.y < opponent.y - 85 ? 0.2 : 0;
          const dashAim = normalize({ x: chaseAim.x, y: chaseAim.y + verticalNudge });
          const hold = clamp((distance - 115) / 900, 0.055, 0.34);
          startAiDash(ai, dashAim, hold, 0.18 + gameplayRandom() * 0.12);
        }

        ai.decisionCooldown = 0.05 + gameplayRandom() * 0.08;
      }
    }

    const aim = ai.dashHeld || ai.punchHeld ? ai.aim : fighter.hitstun > 0 ? hitstunAim : wallAim || chaseAim;
    const input = {
      aim,
      hasAim: true,
      upHeld: false,
      downHeld: false,
      downPressed: false,
      dashHeld: ai.dashHeld,
      dashPressed: ai.dashPressQueued,
      dashReleased: ai.dashReleaseQueued,
      punchHeld: ai.punchHeld,
      punchPressed: ai.punchPressQueued,
      punchReleased: ai.punchReleaseQueued,
    };

    ai.dashPressQueued = false;
    ai.dashReleaseQueued = false;
    ai.punchPressQueued = false;
    ai.punchReleaseQueued = false;
    ai.lastDashHeld = ai.dashHeld;
    ai.lastPunchHeld = ai.punchHeld;
    return input;
  }

  function chooseAiOpponent(fighter) {
    const candidates = fighters.filter((candidate) => candidate !== fighter && candidate.health > 0);
    const pool = candidates.filter((candidate) => isPreferredAiTarget(fighter, candidate));
    let best = null;
    let bestScore = Infinity;
    for (const candidate of pool) {
      if (candidate === fighter || candidate.health <= 0) {
        continue;
      }
      const offset = shortestOffset(fighter, candidate);
      const distance = length(offset);
      const comboBias = candidate === fighter.lastAttacker ? -90 : 0;
      const vulnerableBias = candidate.hitstun > 0 || candidate.juked > 0 ? -65 : 0;
      const attackBias = candidate.attack ? -35 : 0;
      const score = distance + comboBias + vulnerableBias + attackBias;
      if (score < bestScore) {
        bestScore = score;
        best = candidate;
      }
    }
    return best;
  }

  function chooseAiThreat(fighter) {
    let best = null;
    let bestDistance = Infinity;
    for (const candidate of fighters) {
      if (candidate === fighter || candidate.health <= 0) {
        continue;
      }
      if (areSameTeam(fighter, candidate)) {
        continue;
      }
      if (!canFightersAffect(candidate, fighter)) {
        continue;
      }
      const distance = length(shortestOffset(fighter, candidate));
      if (distance < bestDistance && incomingAttackDanger(candidate, fighter, distance)) {
        bestDistance = distance;
        best = candidate;
      }
    }
    return best;
  }

  function getAiRoute(fighter, opponent, directAim) {
    const target = {
      x: opponent.x + opponent.vx * 0.12,
      y: opponent.y + opponent.vy * 0.08,
    };
    const candidates = getAiRouteCandidates(fighter, opponent, target);
    const directCandidate = candidates[0];
    const directBlocker = findAiRouteBlocker(fighter, directCandidate.endpoint);
    const holeCandidate = directBlocker ? getAiHoleRouteCandidate(fighter, opponent) : null;
    if (holeCandidate) candidates.push(holeCandidate);

    const evaluated = candidates.map((candidate) => {
      const offset = {
        x: candidate.endpoint.x - fighter.x,
        y: candidate.endpoint.y - fighter.y,
      };
      const distance = length(offset);
      return {
        ...candidate,
        offset,
        distance,
        score: candidate.score ?? distance,
        blocker: findAiRouteBlocker(fighter, candidate.endpoint),
      };
    });
    const clearRoutes = evaluated.filter((candidate) => !candidate.blocker);
    const chosen = (clearRoutes.length > 0 ? clearRoutes : evaluated).reduce((best, candidate) => {
      if (!best) return candidate;
      const candidateScore = candidate.score + (candidate.blocker ? 420 : 0);
      const bestScore = best.score + (best.blocker ? 420 : 0);
      return candidateScore < bestScore ? candidate : best;
    }, null);

    if (!chosen) {
      return {
        aim: directAim,
        blocker: null,
        distance: length(shortestOffset(fighter, opponent)),
        usesWrap: false,
        requiresMovement: false,
        routeKind: "direct",
        avoidedBlocker: false,
      };
    }

    if (!chosen.blocker) {
      return {
        aim: chosen.distance > 1 ? normalize(chosen.offset) : directAim,
        blocker: null,
        distance: chosen.distance,
        usesWrap: chosen.usesWrap,
        requiresMovement: chosen.usesWrap,
        routeKind: chosen.kind,
        avoidedBlocker: Boolean(directBlocker && chosen.usesWrap),
      };
    }

    const waypoint = chooseAiRouteWaypoint(fighter, opponent, chosen.blocker);
    const aim = normalize({ x: waypoint.x - fighter.x, y: waypoint.y - fighter.y });
    return {
      aim,
      blocker: chosen.blocker,
      distance: Math.hypot(waypoint.x - fighter.x, waypoint.y - fighter.y),
      usesWrap: chosen.usesWrap,
      requiresMovement: true,
      routeKind: `${chosen.kind}-detour`,
      avoidedBlocker: false,
    };
  }

  function getAiRouteCandidates(fighter, opponent, target) {
    const stage = currentStage();
    const xRoutes = [{ shift: 0, label: "direct" }];
    const yRoutes = [{ shift: 0, label: "direct" }];
    if (stage.wrap !== false) {
      const wrapMargin = stage.wrapMargin ?? fighter.data.width * 0.5;
      const span = currentStageWidth() + wrapMargin * 2;
      xRoutes.push({ shift: -span, label: "wrap-left" }, { shift: span, label: "wrap-right" });
    }
    if (stage.verticalWrap) {
      const wrapMargin = stage.verticalWrapMargin ?? 48;
      const span = currentStageHeight() + wrapMargin + fighter.data.height;
      yRoutes.push({ shift: -span, label: "wrap-up" }, { shift: span, label: "wrap-down" });
    }

    const candidates = [];
    for (const xRoute of xRoutes) {
      for (const yRoute of yRoutes) {
        const usesWrap = xRoute.shift !== 0 || yRoute.shift !== 0;
        const kind =
          xRoute.shift !== 0 && yRoute.shift !== 0
            ? `${xRoute.label}+${yRoute.label}`
            : xRoute.shift !== 0
              ? xRoute.label
              : yRoute.label;
        candidates.push({
          endpoint: { x: target.x + xRoute.shift, y: target.y + yRoute.shift },
          kind,
          usesWrap,
        });
      }
    }

    return candidates;
  }

  function getAiHoleRouteCandidate(fighter, opponent) {
    const stage = currentStage();
    const hole = stage.hole;
    if (!hole) return null;
    const halfW = fighter.data.width * 0.5;
    const halfH = fighter.data.height * 0.5;
    const laneMin = hole.x + halfW + 10;
    const laneMax = hole.x + hole.width - halfW - 10;
    if (laneMin >= laneMax) return null;
    const laneX = clamp(hole.x + hole.width * 0.5, laneMin, laneMax);
    const aligned = fighter.x >= laneMin && fighter.x <= laneMax;
    const floorY = stage.floorY ?? currentStageHeight();
    const endpoint = aligned
      ? { x: laneX, y: currentStageHeight() + halfH + 64 }
      : { x: laneX, y: Math.min(fighter.y, floorY - halfH - 26) };
    const exit = { x: laneX, y: -halfH };
    return {
      endpoint,
      kind: aligned ? "hole-wrap-down" : "hole-approach",
      usesWrap: true,
      score:
        Math.hypot(endpoint.x - fighter.x, endpoint.y - fighter.y) +
        Math.hypot(opponent.x - exit.x, opponent.y - exit.y),
    };
  }

  function findAiRouteBlocker(fighter, endpoint) {
    let best = null;
    let bestDistance = Infinity;
    for (const terrain of currentStage().terrain) {
      if (!isAiRouteBlockingTerrain(terrain, fighter, endpoint)) {
        continue;
      }
      const rect = getTerrainRect(terrain);
      if (terrain.kind === "wall" && isStageBoundaryWall(rect)) {
        continue;
      }
      const clearance = clamp(
        Math.min(fighter.data.width, fighter.data.height) * 0.24,
        10,
        AI_ROUTE_CLEARANCE,
      );
      if (!segmentIntersectsExpandedRect(fighter.x, fighter.y, endpoint.x, endpoint.y, rect, clearance)) {
        continue;
      }

      const dx = fighter.x - (rect.x + rect.w * 0.5);
      const dy = fighter.y - (rect.y + rect.h * 0.5);
      const distance = Math.hypot(dx, dy);
      if (distance < bestDistance) {
        bestDistance = distance;
        best = rect;
      }
    }
    return best;
  }

  function isAiRouteBlockingTerrain(terrain, fighter, endpoint) {
    if (terrain.kind !== "oneway") return true;
    const rect = getTerrainRect(terrain);
    const fighterBottom = fighter.y + fighter.data.height * 0.5;
    const movingDownward = endpoint.y > fighter.y + 6;
    return movingDownward && fighterBottom <= rect.y + 10;
  }

  function isStageBoundaryWall(rect) {
    const stageWidth = currentStageWidth();
    const stageHeight = currentStageHeight();
    return (
      (rect.x <= 0 && rect.w >= stageWidth * 0.9) ||
      (rect.y <= 0 && rect.h >= stageHeight * 0.9) ||
      (rect.x + rect.w >= stageWidth && rect.h >= stageHeight * 0.9)
    );
  }

  function chooseAiRouteWaypoint(fighter, opponent, rect) {
    const padding = 108;
    const minX = AI_ROUTE_EDGE_PADDING;
    const minY = AI_ROUTE_EDGE_PADDING;
    const maxX = currentStageWidth() - AI_ROUTE_EDGE_PADDING;
    const maxY = currentStageHeight() - AI_ROUTE_EDGE_PADDING - 24;
    const sideX = fighter.x < rect.x + rect.w * 0.5 ? rect.x - padding : rect.x + rect.w + padding;
    const sideY = fighter.y < rect.y + rect.h * 0.5 ? rect.y - padding : rect.y + rect.h + padding;
    const candidates =
      rect.h > rect.w
        ? [
            { x: sideX, y: rect.y - padding },
            { x: sideX, y: rect.y + rect.h + padding },
            { x: rect.x + rect.w * 0.5, y: sideY },
          ]
        : [
            { x: rect.x - padding, y: sideY },
            { x: rect.x + rect.w + padding, y: sideY },
            { x: sideX, y: rect.y + rect.h * 0.5 },
          ];

    let best = null;
    let bestScore = Infinity;
    for (const candidate of candidates) {
      const waypoint = {
        x: clamp(candidate.x, minX, maxX),
        y: clamp(candidate.y, minY, maxY),
      };
      const score =
        Math.hypot(waypoint.x - fighter.x, waypoint.y - fighter.y) +
        Math.hypot(opponent.x - waypoint.x, opponent.y - waypoint.y) * 0.72;
      if (score < bestScore) {
        bestScore = score;
        best = waypoint;
      }
    }

    return best || { x: fighter.x, y: fighter.y };
  }

  function segmentIntersectsExpandedRect(x1, y1, x2, y2, rect, padding) {
    const expanded = {
      x: rect.x - padding,
      y: rect.y - padding,
      w: rect.w + padding * 2,
      h: rect.h + padding * 2,
    };
    const steps = Math.max(8, Math.ceil(Math.hypot(x2 - x1, y2 - y1) / 90));
    for (let i = 1; i < steps; i += 1) {
      const t = i / steps;
      const x = lerp(x1, x2, t);
      const y = lerp(y1, y2, t);
      if (x >= expanded.x && x <= expanded.x + expanded.w && y >= expanded.y && y <= expanded.y + expanded.h) {
        return true;
      }
    }
    return false;
  }

  function tickAiButton(ai, button, dt) {
    const heldKey = `${button}Held`;
    const timerKey = `${button}Timer`;
    if (!ai[heldKey]) {
      return;
    }
    ai[timerKey] -= dt;
    if (ai[timerKey] <= 0) {
      ai[heldKey] = false;
      ai[timerKey] = 0;
      ai[`${button}ReleaseQueued`] = true;
    }
  }

  function startAiDash(ai, direction, hold, cooldown) {
    ai.aim = length(direction) > 0 ? normalize(direction) : { x: -1, y: 0 };
    ai.dashHeld = true;
    ai.dashPressQueued = true;
    ai.dashReleaseQueued = false;
    ai.dashTimer = hold;
    ai.dashCooldown = cooldown;
  }

  function startAiPunch(ai, direction, hold, cooldown) {
    ai.aim = length(direction) > 0 ? normalize(direction) : { x: -1, y: 0 };
    ai.punchHeld = true;
    ai.punchPressQueued = true;
    ai.punchReleaseQueued = false;
    ai.punchTimer = hold;
    ai.punchCooldown = cooldown;
  }

  function getAiDefensiveAim(direction) {
    const dir = length(direction) > 0 ? normalize(direction) : { x: -1, y: 0 };
    const angle = Math.atan2(dir.y, dir.x) + (gameplayRandom() - 0.5) * AI_DEFENSE_AIM_ERROR;
    return { x: Math.cos(angle), y: Math.sin(angle) };
  }

  function aiPunchRange(fighter) {
    if(fighter.data.spear)return fighter.data.spear.reach*.94;
    if(fighter.reloadRemaining>0)return fighter.data.width*.5+fighter.data.punchReach+fighter.data.punchRadius+38;
    if (fighter.data.projectileConfig) return fighter.data.projectileConfig.aiRange;
    if (fighter.data.projectilePunch) return 480;
    return fighter.data.width * 0.5 + fighter.data.punchReach + fighter.data.punchRadius + 38;
  }

  function incomingAttackDanger(attacker, target, distance) {
    if (!attacker.attack || attacker.attack.selfCancelled || distance > 185) {
      return false;
    }
    const age = attacker.attack.age;
    const aboutToHit = age >= attacker.attack.startup * 0.35 && age <= attacker.attack.startup + attacker.attack.active + 0.08;
    if (!aboutToHit) {
      return false;
    }

    const attackBox = getAttackHitbox(attacker);
    if (attackHitboxOverlapsRect(attackBox, getBodyRect(target), 24)) {
      return true;
    }

    const toTarget = normalize(shortestOffset(attacker, target));
    return dot(attacker.attack.dir, toTarget) > 0.35;
  }

  function getAiWallAim(fighter) {
    if (fighter.onGround || fighter.hitstun > 0 || fighter.airDashes > 0 || fighter.vy < 80) {
      return null;
    }

    let best = null;
    let bestDistance = 190;
    for (const terrain of currentStage().terrain) {
      if (terrain.kind !== "wall") {
        continue;
      }
      const rect = getTerrainRect(terrain);
      const verticalOverlap = fighter.y > rect.y - 120 && fighter.y < rect.y + rect.h + 120;
      if (!verticalOverlap) {
        continue;
      }

      const leftDistance = Math.abs(fighter.x - rect.x);
      const rightDistance = Math.abs(fighter.x - (rect.x + rect.w));
      if (fighter.x < rect.x && leftDistance < bestDistance) {
        bestDistance = leftDistance;
        best = { x: 1, y: 0.08 };
      } else if (fighter.x > rect.x + rect.w && rightDistance < bestDistance) {
        bestDistance = rightDistance;
        best = { x: -1, y: 0.08 };
      }
    }

    if (currentStage().wrap === false) {
      if (fighter.x < 170 && 170 - fighter.x < bestDistance) {
        best = { x: -1, y: 0.08 };
      } else if (currentStageWidth() - fighter.x < 170 && currentStageWidth() - fighter.x < bestDistance) {
        best = { x: 1, y: 0.08 };
      }
    }

    return best ? normalize(best) : null;
  }

  function isSurfaceTechEligible(fighter) {
    return Boolean(
      fighter.knockdownImpactPending &&
      fighter.knockdownSource &&
      fighter.stunType === "knockdown" &&
      fighter.health > 0 &&
      !fighter.koScored
    );
  }

  function getAiSurfaceTechAim(fighter) {
    if (
      !isSurfaceTechEligible(fighter) ||
      fighter.floorTechReady > 0 ||
      fighter.floorTechCooldown > 0 ||
      fighter.floorTechVulnerable > 0
    ) {
      return null;
    }

    const prediction = getSurfaceTechPrediction(fighter, TECH_AI_LOOKAHEAD);
    if (!prediction || prediction.time > TECH_AI_LOOKAHEAD) {
      return null;
    }

    const choice = gameplayRandom();
    if (prediction.surface === "floor") {
      return choice < 0.48 ? { x: 0, y: 1 } : normalize({ x: choice < 0.74 ? -0.82 : 0.82, y: 1 });
    }
    if (prediction.surface === "wall") {
      return normalize({ x: prediction.normal.x, y: choice < 0.34 ? -0.62 : choice > 0.68 ? 0.62 : 0 });
    }
    return normalize({ x: choice < 0.34 ? -0.62 : choice > 0.68 ? 0.62 : 0, y: -1 });
  }

  function getSurfaceTechPrediction(fighter, maxTime = Infinity) {
    if (!isSurfaceTechEligible(fighter)) {
      return null;
    }

    const body = getBodyRect(fighter);
    const velocity = { x: fighter.vx, y: fighter.vy };
    let best = null;

    const consider = (time, normal, rect) => {
      if (!Number.isFinite(time) || time < -0.012 || time > maxTime || (best && time >= best.time)) {
        return;
      }
      const t = Math.max(0, time);
      const projected = {
        x: body.x + velocity.x * t,
        y: body.y + velocity.y * t,
        w: body.w,
        h: body.h,
      };
      const axisOverlap = Math.abs(normal.x) > 0.55
        ? projected.y + projected.h > rect.y + 4 && projected.y < rect.y + rect.h - 4
        : projected.x + projected.w > rect.x + 4 && projected.x < rect.x + rect.w - 4;
      if (!axisOverlap) {
        return;
      }
      best = { time: t, normal, surface: getTechSurface(normal), rect };
    };

    for (const terrain of currentStage().terrain) {
      const rect = getTerrainCollisionRect(terrain, fighter.data.width);
      const oneWay = rect.kind === "oneway";
      if (velocity.y > 1) {
        consider((rect.y - (body.y + body.h)) / velocity.y, { x: 0, y: -1 }, rect);
      }
      if (!oneWay && velocity.y < -1) {
        consider((rect.y + rect.h - body.y) / velocity.y, { x: 0, y: 1 }, rect);
      }
      if (!oneWay && velocity.x > 1) {
        consider((rect.x - (body.x + body.w)) / velocity.x, { x: -1, y: 0 }, rect);
      }
      if (!oneWay && velocity.x < -1) {
        consider((rect.x + rect.w - body.x) / velocity.x, { x: 1, y: 0 }, rect);
      }
    }

    return best;
  }

  function getTechSurface(normal) {
    if (normal.y < -0.55) {
      return "floor";
    }
    if (normal.y > 0.55) {
      return "ceiling";
    }
    return "wall";
  }

  function updateFighterPhysics(fighter, dt) {
    if(isUpperRecovering(fighter))return;
    syncStickyMobility(fighter,Boolean(dashballState?.sticky&&dashballState.ball.carrier===fighter.id));
    updateAirFloatMomentumSource(fighter);
    updateProjectileReload(fighter,dt);
    if(fighter.projectilePressure){
      fighter.projectilePressure.timer=Math.max(0,fighter.projectilePressure.timer-dt);
      if(fighter.projectilePressure.timer<=1e-9)delete fighter.projectilePressure;
    }
    if(fighter.data.punchSequence&&fighter.edgebertChain){
      const chain=fighter.edgebertChain;if(fighter.hitstop<=0)chain.age+=dt;
      if(fighter.hitstun>0||fighter.juked>0||fighter.koScored||fighter.spotDodgeInvuln>0||fighter.spotDodgeRecovery>0||fighter.punchBlockstun>0)resetPunchSequence(fighter);
      else if(chain.age>chain.total+(chain.stage<2?EDGEBERT_SEQUENCE_GRACE:0)&&fighter.edgebertFollowup==null)fighter.edgebertChain=null;
    }
    if(fighter.airDashArc&&!isAirArcActive(fighter))delete fighter.airDashArc;
    fighter.impactFrameFlash=Math.max(0,fighter.impactFrameFlash-dt);
    const firedUpDecayDt=Math.max(0,dt-fighter.firedUpTimer);
    fighter.firedUpTimer=Math.max(0,fighter.firedUpTimer-dt);
    fighter.firedUpHealth=Math.max(0,fighter.firedUpHealth-40*firedUpDecayDt);
    const data = fighter.data;
    fighter.gunRecoil = Math.max(0, fighter.gunRecoil - dt);
    if (fighter.punchVisual&&fighter.hitstop<=0) {
      fighter.punchVisual.age += dt;
      const lifetime=fighter.punchVisual.sequenceTiming?Math.max(.16,fighter.punchVisual.sequenceTiming.total-fighter.punchVisual.sequenceAge):.16;
      if (fighter.punchVisual.age >= lifetime) fighter.punchVisual = null;
    }
    const hadHitstunParryActive = fighter.hitstunParryActive > 0;
    const hadDashEscapeBuffer = fighter.dashEscapeBuffer > 0;
    const wasInHitstop = fighter.hitstop > 0;

    fighter.hitstop = Math.max(0, fighter.hitstop - dt);
    if(fighter.hitstop<1e-9)fighter.hitstop=0;
    if(data.boomerang&&!wasInHitstop){
      fighter.heavyDashRecovery=Math.max(0,(fighter.heavyDashRecovery||0)-dt*fighterStatusScale(fighter,"action"));
      const windup=fighter.heavyDashWindup;
      if(windup){
        if(fighter.hitstun>0||fighter.juked>0||fighter.koScored)delete fighter.heavyDashWindup;
        else {windup.remaining-=dt*fighterStatusScale(fighter,"action");if(windup.remaining<=1e-9){delete fighter.heavyDashWindup;releaseDash(fighter,windup.dir,windup.charge,true);fighter.heavyDashRecovery=data.dashRecovery;}}
      }
    }
    const surfaceTechInvulnerabilityDt = wasInHitstop && fighter.surfaceTechTravelTimer > 0 ? 0 : dt;
    fighter.invulnerable = Math.max(0, fighter.invulnerable - surfaceTechInvulnerabilityDt);
    fighter.dashParry = Math.max(0, fighter.dashParry - dt);
    fighter.escapeWindow = Math.max(0, fighter.escapeWindow - dt);
    fighter.dashEscapeBuffer = Math.max(0, fighter.dashEscapeBuffer - dt);
    fighter.flash = Math.max(0, fighter.flash - dt);
    fighter.cancelFlash = Math.max(0, fighter.cancelFlash - dt);
    fighter.whiffLag = Math.max(0, fighter.whiffLag - dt);
    fighter.punchLockout = Math.max(0, fighter.punchLockout - dt);
    fighter.groundSkidTimer = Math.max(0, fighter.groundSkidTimer - dt);
    fighter.platformDropTimer = Math.max(0, fighter.platformDropTimer - dt);
    if (fighter.platformDropTimer <= 0) {
      fighter.platformDropPlatformId = null;
    }
    fighter.dashCarryTimer = Math.max(0, fighter.dashCarryTimer - dt);
    fighter.tippyJumpTimer = Math.max(0, fighter.tippyJumpTimer - dt);
    if (fighter.tippyJumpTimer <= 0) {
      fighter.tippyJumpSpeedCap = 0;
    }
    fighter.shieldFlash = Math.max(0, fighter.shieldFlash - dt);
    fighter.punchBlockstun = Math.max(0, fighter.punchBlockstun - dt);
    if (fighter.punchBlockstun < 1e-9) fighter.punchBlockstun = 0;
    fighter.shieldRegenDelay = Math.max(0, fighter.shieldRegenDelay - dt);
    fighter.shieldReleaseParry = Math.max(0, fighter.shieldReleaseParry - dt);
    fighter.shieldChargeBleedFlash = Math.max(0, fighter.shieldChargeBleedFlash - dt);
    fighter.shieldReleaseWhiffFlash = Math.max(0, fighter.shieldReleaseWhiffFlash - dt);
    fighter.shieldParrySuccessFlash = Math.max(0, fighter.shieldParrySuccessFlash - dt);
    fighter.dashFromShieldFlash = Math.max(0, fighter.dashFromShieldFlash - dt);
    fighter.shieldReactivationTimer = Math.max(0, fighter.shieldReactivationTimer - dt);
    fighter.shieldReactivationFlash = Math.max(0, fighter.shieldReactivationFlash - dt);
    fighter.mercyDashFlash = Math.max(0, fighter.mercyDashFlash - dt);
    fighter.hitstunParryActive = Math.max(0, fighter.hitstunParryActive - dt);
    fighter.hitstunParryFlash = Math.max(0, fighter.hitstunParryFlash - dt);
    fighter.resourceFlash = Math.max(0, fighter.resourceFlash - dt);
    fighter.clashLostTimer = Math.max(0, fighter.clashLostTimer - dt);
    fighter.forceCrouch = Math.max(0, fighter.forceCrouch - dt);
    fighter.spotDodgeInvuln = Math.max(0, fighter.spotDodgeInvuln - dt);
    fighter.spotDodgeRecovery = Math.max(0, fighter.spotDodgeRecovery - dt);
    fighter.spotDodgeFlash = Math.max(0, fighter.spotDodgeFlash - dt);
    fighter.spotDodgeSuccessFlash = Math.max(0, fighter.spotDodgeSuccessFlash - dt);
    fighter.spotDodgeMissFlash = Math.max(0, fighter.spotDodgeMissFlash - dt);
    fighter.spotDodgeDownTapWindow = Math.max(0, fighter.spotDodgeDownTapWindow - dt);
    fighter.juked = Math.max(0, fighter.juked - dt);
    fighter.jukedFlash = Math.max(0, fighter.jukedFlash - dt);
    fighter.restoreFlash = Math.max(0, fighter.restoreFlash - dt);
    fighter.shieldBreakFlash = Math.max(0, fighter.shieldBreakFlash - dt);
    fighter.parrySuccessFlash = Math.max(0, fighter.parrySuccessFlash - dt);
    fighter.parryMissFlash = Math.max(0, fighter.parryMissFlash - dt);
    fighter.comboEscapeFlash = Math.max(0, fighter.comboEscapeFlash - dt);
    fighter.dashEscapeSuccessFlash = Math.max(0, fighter.dashEscapeSuccessFlash - dt);
    fighter.dashEscapeMissFlash = Math.max(0, fighter.dashEscapeMissFlash - dt);
    fighter.dashReboundDITimer = Math.max(0, fighter.dashReboundDITimer - dt);
    fighter.koLaunchFlash = Math.max(0, fighter.koLaunchFlash - dt);
    updateCorpseLifetime(fighter, dt);
    if (fighter.koCorpseGone) {
      fighter.afterimages = [];
      return;
    }
    fighter.knockdownTimer = Math.max(0, fighter.knockdownTimer - dt);
    fighter.knockdownTechFlash = Math.max(0, fighter.knockdownTechFlash - dt);
    fighter.dashReboundFlash = Math.max(0, fighter.dashReboundFlash - dt);
    fighter.dashReboundMissFlash = Math.max(0, fighter.dashReboundMissFlash - dt);
    fighter.mutualDashReboundFlash = Math.max(0, fighter.mutualDashReboundFlash - dt);
    fighter.dashReboundLockout = Math.max(0, fighter.dashReboundLockout - dt);
    fighter.wallContactGrace = Math.max(0, fighter.wallContactGrace - dt);
    if (fighter.wallContactGrace <= 0) {
      fighter.wallContactNormalX = 0;
      fighter.wallContactId = null;
    }
    const hadFloorTechReady = fighter.floorTechReady > 0;
    fighter.floorTechReady = Math.max(0, fighter.floorTechReady - dt);
    fighter.floorTechCooldown = Math.max(0, fighter.floorTechCooldown - dt);
    fighter.floorTechFlash = Math.max(0, fighter.floorTechFlash - dt);
    fighter.floorTechVulnerable = Math.max(0, fighter.floorTechVulnerable - dt);
    const wasSurfaceTechTraveling = fighter.surfaceTechTravelTimer > 0;
    const surfaceTechTravelDt = fighter.hitstop > 0 ? 0 : dt;
    fighter.surfaceTechTravelTimer = Math.max(0, fighter.surfaceTechTravelTimer - surfaceTechTravelDt);
    if (wasSurfaceTechTraveling && fighter.surfaceTechTravelTimer <= 0) {
      fighter.vx *= 0.24;
      fighter.surfaceTechTravelDirection = 0;
    }

    if (hadFloorTechReady && fighter.floorTechReady <= 0 && fighter.hitstun > 0) {
      fighter.floorTechFlash = Math.max(fighter.floorTechFlash, 0.08);
    }

    if (hadHitstunParryActive && fighter.hitstunParryActive <= 0 && fighter.hitstunParryMissPending) {
      resolveHitstunParryMiss(fighter);
    }

    if (hadDashEscapeBuffer && fighter.dashEscapeBuffer <= 0) {
      resolveBufferedComboEscapeMiss(fighter);
    }

    updateShieldDashReactivation(fighter);

    updateShieldResource(fighter,dt);

    updateSpotDodgeState(fighter);
    updateComboResilienceMeters(fighter, dt);
    updateAnimationState(fighter);

    if (wasInHitstop || roundResetTimer > 0) {
      if(!wasInHitstop||fighter.attack?.projectile)updateAttack(fighter, dt);
      updateAnimationState(fighter);
      return;
    }

    updateMercyDash(fighter, dt);

    if (fighter.hitstun > 0) {
      fighter.hitstun = Math.max(0, fighter.hitstun - dt);
      if (fighter.hitstun <= 0) {
        releaseBankedAirDashes(fighter);
        fighter.stunType = "";
        fighter.knockdownTimer = 0;
        fighter.knockdownImpactPending = false;
        fighter.knockdownSource = null;
        fighter.floorTechReady = 0;
        fighter.floorTechMissArmed = false;
        fighter.surfaceTechTarget = "";
        fighter.surfaceBounceSource = "";
        fighter.surfaceBounceCount = 0;
      }
    }

    if (fighter.comboHits > 0) {
      if (fighter.hitstun > 0 && fighter.stunType !== "floorTech") {
        fighter.comboGrace = Math.max(fighter.comboGrace, COMBO_BASE_GRACE);
      } else {
        fighter.comboGrace -= dt;
        if (fighter.comboGrace <= 0) {
          breakComboOwnership(fighter);
        }
      }
    }

    const juggling = isJuggleState(fighter);
    const airDashCharging = isAirDashCharging(fighter);
    const airDashFullyCharged = airDashCharging && fighter.dashCharge >= data.dashChargeTime;
    let gravityScale = juggling ? data.juggleGravityScale : 1;
    if(isAirArcActive(fighter))gravityScale=0;
    if (airDashCharging) {
      gravityScale *= getAirDashChargeGravityScale(fighter, airDashFullyCharged);
    }

    const gravity = gravityVector();
    const airFloat = !fighter.onGround && data.airFloat;
    const fallGravity = airFloat
      ? (fighter.floatMotion==="external"?(airFloat.externalGravity??data.gravity):airFloat.gravity * lerp(1, airFloat.upGravityScale, getAirFloatUpInput(fighter)))
      : data.gravity;
    fighter.vx += fallGravity * gravityScale * gravity.x * dt;
    fighter.vy += fallGravity * gravityScale * gravity.y * dt;
    const icy=iceUnderFighter(fighter);
    const groundFriction = icy?Math.max(data.groundFriction,Ice.TUNING.friction):fighter.groundSkidTimer > 0 ? 0.988 : data.groundFriction;
    const airDrag = isAirArcActive(fighter) ? Math.pow(DASH_CARRY_AIR_DRAG,1/data.airDashArc.durationScale)
      : fighter.dashCarryTimer > 0 ? DASH_CARRY_AIR_DRAG : data.airDrag;
    fighter.vx *= juggling ? data.juggleDrag : fighter.onGround && stageGravityAxis === "y" ? groundFriction : airDrag;
    fighter.vy *= juggling ? data.juggleVerticalDrag : fighter.onGround && stageGravityAxis === "x" ? groundFriction : 0.999;
    if (!fighter.onGround) {
      fighter.tippyToes = false;
      fighter.tippyToesHold = 0;
      fighter.crouching = false;
    } else if (fighter.forceCrouch > 0) {
      fighter.tippyJumpTimer = 0;
      fighter.tippyJumpSpeedCap = 0;
      fighter.tippyToes = false;
      fighter.tippyToesHold = 0;
      fighter.crouching = true;
    } else {
      fighter.tippyJumpTimer = 0;
      fighter.tippyJumpSpeedCap = 0;
    }
    applyCrouchBrake(fighter, dt);
    applyGroundWalk(fighter, dt);
    applyAirDashChargeHover(fighter, dt, airDashFullyCharged);
    applyAirDashSteering(fighter, dt);
    if (data.weavingDash && fighter.hitstun <= 0 && !fighter.chargingDash &&
        (fighter.dashCarryTimer > 0 || fighter.groundSkidTimer > 0)) {
      fighter.dashWeaveAge += dt;
      const wave = Math.sin(fighter.dashWeaveAge * 19) * fighter.dashWeaveSign;
      if (fighter.onGround) {
        fighter.vx *= 1 + wave * 2.5 * dt;
      } else {
        const angle = wave * 3.2 * dt;
        const vx = fighter.vx;
        fighter.vx = vx * Math.cos(angle) - fighter.vy * Math.sin(angle);
        fighter.vy = vx * Math.sin(angle) + fighter.vy * Math.cos(angle);
      }
    }
    applyAirFloatDashDrag(fighter,dt);
    applyAirFloatControl(fighter, dt);
    applyFreeFallControl(fighter, dt);
    applyHitstunDI(fighter, dt);
    applyTerminalVelocity(fighter, juggling);
    if(isPhantomGhost(fighter)){
      fighter.vx=fighter.phantomDash.dir.x*fighter.phantomDash.speed;
      fighter.vy=fighter.phantomDash.dir.y*fighter.phantomDash.speed;
    }
    updateTumble(fighter, dt);
    if (fighter.surfaceTechTravelTimer > 0) {
      fighter.vx = fighter.surfaceTechTravelDirection * (TECH_ROLL_DISTANCE / TECH_ROLL_TRAVEL_TIME);
      fighter.vy = 0;
    }

    fighter.prevX = fighter.x;
    fighter.prevY = fighter.y;
    fighter.x += fighter.vx * dt;
    fighter.y += fighter.vy * dt;

    wrapFighter(fighter);
    if(isUpperRecovering(fighter))return;
    resolveTerrain(fighter, dt);
    if(data.ice){
      const point=iceTrailPoint(fighter);
      Ice.sampleAir(fighter.ice,point,dt,shortestOffset,fighter.onGround||fighter.wallSliding||fighter.hitstun>0||fighter.dashCarryTimer<=0,normalizeIcePoint);
      const surface=iceSupport(fighter);Ice.sampleGround(fighter.ice,surface,surface?iceSurfaceAlong(fighter,surface):0,dt);
    }
    if(data.ember){
      const ground=fighter.ember.trail?.ground,surface=ground?iceSupport(fighter):null,point=ground?groundFeedbackContact(fighter):fighter;
      Ember.sample(fighter.ember,{x:point.x,y:point.y},dt,shortestOffset,
        ground?!surface||fighter.hitstun>0||fighter.groundSkidTimer<=0:fighter.onGround||fighter.wallSliding||fighter.hitstun>0||fighter.dashCarryTimer<=0,
        normalizeIcePoint,surface);
    }
    if(currentStage().volleyball){
      const x=fighter.x;Dashball.constrain(dashballState,fighter,currentStage());
      if(isPhantomGhost(fighter)&&fighter.x!==x)fighter.phantomDash.terrainStopped=true;
    }
    if(isPhantomGhost(fighter)){
      fighter.phantomDash.remaining=Math.max(0,fighter.phantomDash.remaining-dt);
      if(fighter.phantomDash.remaining<=1e-8||fighter.onGround||fighter.phantomDash.terrainStopped){
        endPhantomDash(fighter);
      }
    }
    updateGroundDefenseRefill(fighter, dt);
    updateAttack(fighter, dt);

    fighter.afterimages.push({
      x: fighter.x,
      y: fighter.y,
      w: data.width,
      h: data.height,
      angle: fighter.angle,
      life: 0.18,
      color: data.color,
    });
    if (fighter.afterimages.length > 9) {
      fighter.afterimages.shift();
    }
    for (const image of fighter.afterimages) {
      image.life -= dt;
    }
    fighter.afterimages = fighter.afterimages.filter((image) => image.life > 0);
    updateAnimationState(fighter);
  }

  function updateAttack(fighter, dt) {
    if (!fighter.attack) {
      return;
    }
    const previousAge = fighter.attack.age;
    if(fighter.data.spear)fighter.attack.previousAge=previousAge;
    fighter.attack.age += dt;
    if(fighter.data.spear){
      const a=fighter.attack,extension=lerp(...fighter.data.spear.extension,a.charge);
      rearmSpearTipContacts(fighter);
      if(previousAge<a.startup&&a.age>=a.startup)playAudioEvent("lancerThrust",{fighter,charge:a.charge});
      if(previousAge<a.startup+extension*.7&&a.age>=a.startup+extension*.7)playAudioEvent("lancerPierce",{fighter,charge:a.charge});
    }
    const shot = fighter.attack.projectile;
    if (shot && fighter.attack.age >= fighter.attack.startup) {
      if (!shot.spawned) {
        if(fighter.data.boomerang&&hasActiveBoomerang(fighter)){fighter.attack=null;return;}
        if(fighter.data.projectileConfig?.magazine){
          if(fighter.reloadRemaining>0||fighter.ammo<=0){fighter.attack=null;return;}
          fighter.ammo--;
          if(fighter.ammo===0)fighter.reloadRemaining=projectileReloadTime(fighter);
        }
        const dir = fighter.attack.dir;
        const muzzle = Math.abs(dir.x) * fighter.data.width * 0.5 + Math.abs(dir.y) * fighter.data.height * 0.5 + 18;
        shot.x = fighter.x + dir.x * muzzle;
        shot.y = fighter.y + dir.y * muzzle;
        if(fighter.data.boomerang){
          const gravity=gravityVector(),tangent={x:gravity.y,y:-gravity.x},sign=dot(dir,tangent)<-.1?-1:1;
          shot.x=fighter.x+tangent.x*sign*fighter.data.throwHandX+gravity.x*fighter.data.throwHandY;
          shot.y=fighter.y+tangent.y*sign*fighter.data.throwHandX+gravity.y*fighter.data.throwHandY;
          shot.boomerang=Boomerang.create(shot.speed,dir,fighter.id);
        }
        if (fighter.data.twinGuns) {
          shot.x -= dir.y * fighter.gunSide * 10;
          shot.y += dir.x * fighter.gunSide * 10;
          fighter.gunSide *= -1;
        }
        shot.spawned = true;
        playAudioEvent("punchSwing",{fighter,charge:fighter.attack.charge,projectileExecuted:true,intensity:.65+fighter.attack.charge*.25});
        fighter.gunRecoil = 0.12;
        if (fighter.data.independentProjectiles) {
          const fired = fighter.attack;
          fired.age = fired.startup;
          if (shot.persistent) {
            shot.creatorId = fighter.id;
            shot.ownerId = fighter.id;
            shot.ownerTeam = fighter.team;
            shot.id = fired.id;
            shot.spawnOrder = fired.id;
            shot.generation = 0;
            shot.kickoffReady = false;
            setProjectileVelocity(fired, multiply(fired.dir, shot.speed));
            enforceProjectileCap(fighter);
          } else {
            for (const old of fighter.projectiles) {
              if (!old.reflectedOwnerId) burst(old.projectile.x, old.projectile.y, 6, fighter.data.lightColor, 2);
            }
            fighter.projectiles = fighter.projectiles.filter((old) => old.reflectedOwnerId);
          }
          fighter.projectiles.push(fired);
          fighter.attack = null;
          if(fighter.data.boomerang)fighter.punchVisual={dir:{...fired.dir},charge:fired.charge,age:0};
          const recovery = Math.max(fired.recovery, fighter.data.punchWhiffLag/(fired.actionSpeed||1));
          fighter.whiffLag = Math.max(fighter.whiffLag, recovery);
          fighter.punchLockout = Math.max(fighter.punchLockout, recovery);
          return;
        }
      } else {
        const previous = { x: shot.x, y: shot.y };
        shot.x += fighter.attack.dir.x * shot.speed * dt;
        shot.y += fighter.attack.dir.y * shot.speed * dt;
        const hitTerrain = currentStage().terrain.some((terrain) => terrain.kind !== "oneway" &&
          segmentIntersectsRect(previous.x, previous.y, shot.x, shot.y, expandRect(getTerrainRect(terrain), shot.radius)));
        if (hitTerrain) fighter.attack.total = fighter.attack.age;
      }
    }
    updateActivePunchAim(fighter, dt);
    if(fighter.attack.sequenceStage!==undefined&&fighter.edgebertChain)fighter.edgebertChain.dir={...fighter.attack.dir};
    if (fighter.data.swordPunch && !fighter.attack.swordPhase &&
        fighter.attack.age >= fighter.attack.startup + fighter.attack.active) {
      fighter.attack = createSwordFollowup(fighter.attack);
      return;
    }
    if (fighter.attack.age >= fighter.attack.total) {
      if(fighter.data.automaticSequence&&fighter.attack.sequenceStage<2&&!fighter.attack.clashed&&!fighter.attack.selfCancelled){
        fighter.attack=createSequenceFollowup(fighter,fighter.attack);return;
      }
      if (!fighter.data.noWhiffPenalty && fighter.attack.hitTargets.size === 0 && !fighter.attack.clashed && !fighter.attack.priorHit) {
        const chargePenalty = fighter.attack.charge * 0.16;
        const lag = (getPunchProfile(fighter).punchWhiffLag + (fighter.data.punchWhiffCharge||0)*fighter.attack.charge**2 + chargePenalty)/(fighter.attack.actionSpeed||1);
        fighter.whiffLag = Math.max(fighter.whiffLag, lag);
        fighter.punchLockout = Math.max(fighter.punchLockout, lag);
        fighter.flash = Math.max(fighter.flash, 0.12);
        sparkText(fighter.x, fighter.y - 58, "WHIFF", "#d7d2c8");
      }
      fighter.attack = null;
    }
  }

  function projectileOwner(shooter, attack) {
    return attack.reflectedOwnerId ? fighters.find(f => f.id === attack.reflectedOwnerId) : shooter;
  }

  function projectileReloadTime(fighter){return fighter.data.projectileConfig?.reloadTime??1.8;}

  function updateProjectileReload(fighter,dt){
    if(!(fighter.reloadRemaining>0))return;
    fighter.reloadRemaining=Math.max(0,fighter.reloadRemaining-dt*fighterStatusScale(fighter,"action"));
    if(fighter.reloadRemaining<=1e-9){fighter.reloadRemaining=0;fighter.ammo=fighter.data.projectileConfig.magazine;}
  }

  function projectilePressure(target,shot){
    if(!shot?.pressure)return 1;
    const pressure=target.projectilePressure||{count:0,timer:0};
    pressure.count++;pressure.timer=PROJECTILE_PRESSURE_RESET;target.projectilePressure=pressure;
    return Math.max(0,1-(pressure.count-1)*.22);
  }

  function setProjectileVelocity(attack, velocity) {
    const shot = attack.projectile;
    const speed = length(velocity), capped = Math.min(speed, shot.maxSpeed ?? speed);
    const dir = speed > 0 ? normalize(velocity) : attack.dir;
    attack.dir = { ...dir };
    shot.speed = capped;
    if (shot.persistent) { shot.vx = dir.x * capped; shot.vy = dir.y * capped; }
  }

  function renewProjectileContact(attack) {
    if (!attack.projectile.persistent) return;
    attack.projectile.generation += 1;
    attack.contactId = `${attack.id}.${attack.projectile.generation}`;
    attack.hitTargets = new Set();
    attack.selfCancelled = false;
  }

  function emitProjectileCue(attack, kind = "impact") {
    const sprite = PRESENTATION_ART.effects?.[kind];
    if (!sprite) return;
    const life = sprite.frames / sprite.fps;
    effects.push({ x: attack.projectile.x, y: attack.projectile.y, life, maxLife: life, sprite, scale: 1 });
  }

  function removeProjectile(attack) {
    attack.projectile.removed = true;
    if(attack.projectile.boomerang)Boomerang.resetRecall(attack.projectile);
    emitProjectileCue(attack, "dash");
  }

  function enforceProjectileCap(owner, reserve = 1) {
    const cap=owner.data.projectileConfig?.cap??REFLECTED_PROJECTILE_CAP;
    const entries = [];
    for (const shooter of fighters) for (const attack of shooter.projectiles) {
      if (!attack.projectile.removed && (projectileOwner(shooter, attack) === owner || owner.data.boomerang&&attack.projectile.boomerang&&attack.projectile.creatorId===owner.id)) entries.push(attack);
    }
    entries.sort((a, b) => (a.projectile.spawnOrder ?? a.id) - (b.projectile.spawnOrder ?? b.id));
    while (entries.length + reserve > cap) removeProjectile(entries.shift());
    if (reserve) for (const shooter of fighters) shooter.projectiles = shooter.projectiles.filter(a => !a.projectile.removed);
  }

  function clearControlledProjectiles(owner) {
    for (const shooter of fighters) {
      for (const attack of shooter.projectiles) if (projectileOwner(shooter, attack) === owner) removeProjectile(attack);
      shooter.projectiles = shooter.projectiles.filter(a => !a.projectile.removed);
    }
  }

  function projectileTerrainContact(paths, radius) {
    let best = null;
    for (const terrain of currentStage().terrain) {
      const surface = getTerrainRect(terrain), rect = expandRect(surface, radius);
      for (const path of paths) {
        if (terrain.kind === "oneway") {
          if (path.y2 <= path.y1 || path.y1 > surface.y - radius + .001) continue;
          const t = (surface.y - radius - path.y1) / (path.y2 - path.y1);
          const x = lerp(path.x1, path.x2, t);
          if (t >= 0 && t <= 1 && x >= rect.x && x <= rect.x + rect.w && (!best || t < best.t)) {
            best = { t, x, y: surface.y - radius, normal: { x: 0, y: -1 } };
          }
          continue;
        }
        if (!segmentIntersectsRect(path.x1, path.y1, path.x2, path.y2, rect)) continue;
        const inside = rectRectCollision({ x: path.x1 - .001, y: path.y1 - .001, w: .002, h: .002 }, rect);
        if (inside && inside.penetration > 0) {
          if (!best || best.t > 0) best = { t: 0, normal: { x: inside.nx, y: inside.ny },
            x: path.x1 + inside.nx * inside.penetration, y: path.y1 + inside.ny * inside.penetration };
          continue;
        }
        let enter = 0, exit = 1, normal = null;
        for (const [axis, start, delta, low, high] of [
          ["x", path.x1, path.x2 - path.x1, rect.x, rect.x + rect.w],
          ["y", path.y1, path.y2 - path.y1, rect.y, rect.y + rect.h],
        ]) {
          if (Math.abs(delta) < 1e-9) continue;
          const near = ((delta > 0 ? low : high) - start) / delta;
          const far = ((delta > 0 ? high : low) - start) / delta;
          if (near >= enter) { enter = near; normal = axis === "x" ? { x: -Math.sign(delta), y: 0 } : { x: 0, y: -Math.sign(delta) }; }
          exit = Math.min(exit, far);
        }
        if (!normal || enter < 0 || enter > exit || enter > 1) continue;
        if (!best || enter < best.t) best = { t: enter, normal,
          x: lerp(path.x1, path.x2, enter), y: lerp(path.y1, path.y2, enter) };
      }
    }
    return best;
  }

  function resolvePersistentTerrain(shooter, attack, paths) {
    const shot = attack.projectile, contact = projectileTerrainContact(paths, shot.radius);
    if (!contact) return false;
    shot.x = contact.x + contact.normal.x * .5;
    shot.y = contact.y + contact.normal.y * .5;
    if(shot.boomerang){
      const owner=projectileOwner(shooter,attack);
      const outbound=shot.boomerang.phase==="outbound";
      Boomerang.wallTurn(shot,shortestOffset(shot,owner),contact.normal);
      attack.dir={x:Math.cos(shot.boomerang.heading),y:Math.sin(shot.boomerang.heading)};
      if(outbound)renewProjectileContact(attack);
      return true;
    }
    if (shot.terrainBounce) {
      const velocity = multiply(attack.dir, shot.speed), along = dot(velocity, contact.normal);
      if (along < 0) setProjectileVelocity(attack, { x: velocity.x - 2 * along * contact.normal.x, y: velocity.y - 2 * along * contact.normal.y });
      emitProjectileCue(attack);
    } else {
      // Lodged arrows are presentation only, never active colliders or resources.
      const sprite = ASSET_SPRITES[shooter.data.spriteSet]?.arrowSprite;
      if (sprite) effects.push({ x: shot.x - contact.normal.x * shot.radius, y: shot.y - contact.normal.y * shot.radius,
        life: .28, maxLife: .28, scale: 2, rotation: Math.atan2(attack.dir.y, attack.dir.x),
        sprite: { ...sprite, frames: 1, stuckArrow: true } });
      shot.removed = true;
    }
    return true;
  }

  function tryProjectileKickoff(owner, attack, paths) {
    if(owner.data.phantomDash||isUpperRecovering(owner))return false;
    const shot = attack.projectile, contactRect = getDashReboundContactRect(owner);
    const targetRect = { x: shot.x - shot.radius, y: shot.y - shot.radius, w: shot.radius * 2, h: shot.radius * 2 };
    const travel = shortestOffset({ x: owner.prevX, y: owner.prevY }, owner);
    const relative = paths.map(p => ({ x1: p.x1 + travel.x, y1: p.y1 + travel.y, x2: p.x2, y2: p.y2 }));
    const touching = relative.some(p => segmentIntersectsRect(p.x1, p.y1, p.x2, p.y2, expandRect(openSoccerRect(contactRect,(p.x1+p.x2)/2,(p.y1+p.y2)/2), shot.radius + DASH_REBOUND_LATERAL_BONUS)));
    if (!shot.kickoffReady) { if (!touching) shot.kickoffReady = true; return false; }
    if (!touching || !owner.data.projectileConfig || !isActiveAirDash(owner) || owner.dashReboundLockout > 0 ||
        owner.hitstun > 0 || owner.juked > 0 || owner.punchBlockstun > 0 || owner.shieldPressureRearm ||
        owner.punchPursuitActive || owner.punchInputHeld || owner.punchPending || owner.chargingPunch || owner.attack) return false;
    const previousTarget = { x: paths[0].x1, y: paths[0].y1 };
    if (!hasDashReboundThroughTrajectory(owner, previousTarget, contactRect, targetRect)) return false;
    const dir = normalize({ x: owner.vx, y: owner.vy });
    const speed = length({ x: owner.vx, y: owner.vy });
    const impulse = DASH_REBOUND_DEFENDER_FORCE + speed * .75;
    setProjectileVelocity(attack, { x: attack.dir.x * shot.speed * .2 + dir.x * impulse, y: attack.dir.y * shot.speed * .2 + dir.y * impulse });
    renewProjectileContact(attack);
    shot.kickoffReady = false;
    const clearance = Math.abs(dir.x) * owner.data.width / 2 + Math.abs(dir.y) * getBodyHeight(owner) / 2 + shot.radius + 22;
    shot.x = owner.x + dir.x * clearance; shot.y = owner.y + dir.y * clearance;
    if(shot.boomerang)Boomerang.redirect(shot,attack.dir);
    confirmObjectHit(owner, { id: attack.id, dir, charge: 0 }, true, true, { id: shot.id });
    emitProjectileCue(attack, "clash");
    return true;
  }

  function hasActiveBoomerang(fighter){
    return fighters.some(shooter=>shooter.projectiles.some(a=>a.projectile.boomerang&&!a.projectile.removed&&(a.projectile.creatorId===fighter.id||projectileOwner(shooter,a)===fighter)));
  }

  function attackContactEntity(key){
    const [kind,id]=key.split(":");
    if(kind==="fighter")return fighters.find(f=>f.id===id&&!f.koScored)||null;
    if(kind==="ball")return dashballState&&Dashball.balls(dashballState).find(b=>String(b.id??"primary")===id)||null;
    if(kind==="bag")return sandbagState?.bags.find(b=>String(b.id)===id)||null;
    if(kind==="golden"){const g=dashballState?.golden;return g?.active&&String(g.serial)===id?g:null;}
    return null;
  }
  function attackContactShape(key){
    const entity=attackContactEntity(key);if(!entity)return null;
    return key.startsWith("fighter:")?getBodyRect(entity):key.startsWith("bag:")?Sandbag.body(entity):entity;
  }
  function boomerangOverlaps(shot,shape){
    const center=shape.r?shape:{x:shape.x+shape.w/2,y:shape.y+shape.h/2},offset=shortestOffset(shot,center);
    if(shape.r)return Math.hypot(offset.x,offset.y)<=shot.radius+shape.r+1;
    return Boolean(Dashball.circleRect({x:shot.x,y:shot.y,r:shot.radius+1},{...shape,x:shot.x+offset.x-shape.w/2,y:shot.y+offset.y-shape.h/2}));
  }
  function beginBoomerangReturn(attack,owner){
    if(!owner||attack.projectile.boomerang.phase==="return")return;
    const offset=shortestOffset(attack.projectile,owner);Boomerang.returning(attack.projectile,offset);
    attack.dir=normalize(offset);attack.projectile.vx=attack.projectile.vy=0;renewProjectileContact(attack);
  }
  function prepareBoomerangs(dt){
    if(sandbagState?.phase==="finished"||dashballState?.phase==="finished")return;
    for(const shooter of fighters)for(const attack of shooter.projectiles){
      const shot=attack.projectile,b=shot.boomerang;if(!b||shot.removed)continue;
      const owner=projectileOwner(shooter,attack),creator=fighters.find(f=>f.id===shot.creatorId);
      if(!owner||!creator||owner.koScored||creator.koScored||roundResetTimer>0){shot.removed=true;Boomerang.resetRecall(shot);continue;}
      for(const key of Object.keys(b.contacts)){const shape=attackContactShape(key);if(!shape||!boomerangOverlaps(shot,shape))delete b.contacts[key];}
      Boomerang.chargeRecall(shot,dt,owner.punchInputHeld,owner.id);
      const result=Boomerang.steer(shot,dt,shortestOffset(shot,owner));attack.dir=result.dir;
      if(result.transitioned)renewProjectileContact(attack);
    }
  }

  function updateFreeProjectiles(dt) {
    const icePaths=fighters.some(f=>f.data.ice||f.data.ember)?[]:null;
    prepareBoomerangs(dt);
    const clashMovement = resolveProjectileClashes(dt);
    for (const shooter of fighters) {
      const previousProjectiles=shooter.projectiles;
      shooter.projectiles = shooter.projectiles.filter((attack) => {
        if(sandbagState?.phase==="finished"||dashballState?.golden&&dashballState.phase==="finished")return true;
        if (attack.projectile.removed) return false;
        const owner = projectileOwner(shooter, attack);
        if (!owner) return false;
        if (owner.koScored || roundResetTimer > 0) return false;
        const shot = attack.projectile;
        if(shot.boomerang&&fighters.find(f=>f.id===shot.creatorId)?.koScored)return false;
        if (shot.persistent || attack.reflectedOwnerId) {
          shot.remainingLife = (shot.remainingLife ?? 6.7) - dt;
          if (shot.remainingLife <= 0) { if (shot.persistent) emitProjectileCue(attack, "dash"); return false; }
        }
        if (shot.persistent) { shot.ownerId = owner.id; shot.ownerTeam = owner.team; }
        const previous = { x: shot.x, y: shot.y };
        const movementDt = clashMovement.get(attack) ?? dt;
        shot.x += attack.dir.x * shot.speed * movementDt;
        shot.y += attack.dir.y * shot.speed * movementDt;
        const paths = wrapProjectile(shot, previous);
        if(icePaths)icePaths.push({id:attack.id,attack,paths,radius:shot.radius});
        if(isUpperRecovering(shot))return true;
        if (shot.persistent) {
          if (resolvePersistentTerrain(shooter, attack, paths)) return !shot.removed;
          if(shot.boomerang?.phase==="return"&&paths.some(p=>segmentIntersectsRect(p.x1,p.y1,p.x2,p.y2,expandRect(openSoccerRect(getBodyRect(owner),(p.x1+p.x2)/2,(p.y1+p.y2)/2),shot.radius*.25))))return false;
          if (tryProjectileKickoff(owner, attack, paths)) return true;
        }
        if (!shot.persistent && currentStage().terrain.some((terrain) => terrain.kind !== "oneway" &&
          paths.some((path) => segmentIntersectsRect(path.x1, path.y1, path.x2, path.y2, expandRect(getTerrainRect(terrain), shot.radius))))) {
          emitProjectileImpact(shooter,attack);
          return false;
        }
        iceProjectileContact(paths,shot.radius);
        if(!isPhantomGhost(owner))emberProjectileContact(paths,shot.radius);
        if(isPhantomGhost(owner))return true;
        if(dashballProjectileContact(owner,attack,paths)){emitProjectileImpact(shooter,attack);if(!shot.boomerang)return Boolean(shot.persistent);}
        for (const reflector of fighters) {
          if (reflector === owner || reflector.koScored || !canFightersAffect(owner, reflector) ||
              !isAttackActive(reflector) || reflector.attack.projectile) continue;
          const punchBox = getAttackHitbox(reflector);
          const contact = findProjectilePunchContact(paths, punchBox, shot.radius);
          if (!contact) continue;
          const direction = normalize(reflector.attack.dir);
          recoverPunchShield(reflector,reflector.attack,`projectile:${attack.contactId??attack.id}`,getAttackDamage(reflector,reflector.attack));
          reflectProjectile(attack,reflector,direction,contact);
          confirmHit(reflector);
          reflector.hitstop = Math.max(reflector.hitstop, 0.035);
          burst(contact.x, contact.y, 18, reflector.data.lightColor, 6);
          sparkText(contact.x, contact.y - 30, "REFLECT", reflector.data.lightColor);
          playAudioEvent("clash", { fighter: reflector, intensity: 0.8 });
          return !shot.removed;
        }
        const control = currentStage().gravitySwitch;
        if (control && gravitySwitchCooldown <= 0) {
          const switchRect = {
            x: control.x - control.radius - shot.radius,
            y: control.y - control.radius - shot.radius,
            w: (control.radius + shot.radius) * 2,
            h: (control.radius + shot.radius) * 2,
          };
          if (paths.some((path) => segmentIntersectsRect(path.x1, path.y1, path.x2, path.y2, switchRect))) {
            activateGravitySwitch(owner, attack);
            emitProjectileImpact(shooter,attack);
            return false;
          }
        }
        const savedAttack = owner.attack;
        owner.attack = attack;
        let consumed = false;
        try {
          for (const target of fighters) {
            if (target === owner || target.koScored || !canFightersAffect(owner, target)&&!courtPunchContact(owner,target)) continue;
            if(shot.boomerang?.contacts[`fighter:${target.id}`])continue;
            if (attack.hitTargets.has(target.id)) continue;
            if (target.invulnerable > 0 && target.spotDodgeInvuln <= 0) continue;
            const padding = shot.radius + (shieldCoversAttack(target, owner, attack) ? getShieldPadding(target) : 0);
            if (!paths.some((path) => segmentIntersectsRect(path.x1, path.y1, path.x2, path.y2, expandRect(openSoccerRect(getBodyRect(target),(path.x1+path.x2)/2,(path.y1+path.y2)/2), padding)))) continue;
            if(shot.boomerang)owner.attack=attack;
            resolveHit(owner, target, getAttackHitbox(owner));
            if(shot.boomerang)shot.boomerang.contacts[`fighter:${target.id}`]=true;
            consumed = !shot.persistent && attack.reflectedOwnerId !== target.id;
            if (shot.persistent && attack.reflectedOwnerId !== target.id) {
              attack.hitTargets.add(target.id);
              emitProjectileImpact(shooter, attack);
              if (target.punchBlockstun > 0) {
                setProjectileVelocity(attack, multiply(attack.dir, -shot.speed));
                if(shot.boomerang){
                  if(shot.boomerang.phase==="outbound")beginBoomerangReturn(attack,owner);
                  else shot.boomerang.heading=Math.atan2(attack.dir.y,attack.dir.x);
                }
              }
            }
            if(!shot.boomerang||attack.reflectedOwnerId===target.id||target.punchBlockstun>0)break;
          }
        } finally {
          owner.attack = owner.hitstun > 0 || owner.juked > 0 ? null : savedAttack;
        }
        if(!consumed&&sandbagState){
          if(shot.boomerang){
            for(const bag of sandbagState.bags){
              const key=`bag:${bag.id}`;if(shot.boomerang.contacts[key])continue;
              const rect=Sandbag.body(bag);
              if(paths.some(p=>segmentIntersectsRect(p.x1,p.y1,p.x2,p.y2,expandRect(rect,shot.radius)))&&Sandbag.hit(sandbagState,owner,attack,bag,sandbagWorld(0)))shot.boomerang.contacts[key]=true;
            }
          }else consumed=Sandbag.projectile(sandbagState,owner,attack,paths,sandbagWorld(0));
        }
        if(consumed)emitProjectileImpact(shooter,attack);
        return !shot.removed && (shot.persistent || !consumed);
      });
      for(const attack of previousProjectiles)if(attack.projectile.boomerang&&!shooter.projectiles.includes(attack))Boomerang.resetRecall(attack.projectile);
    }
    for (const shooter of fighters) shooter.projectiles = shooter.projectiles.filter(a => !a.projectile.removed);
    return icePaths;
  }

  function emitProjectileImpact(shooter,attack) {
    const sprite=ASSET_SPRITES[shooter.data.spriteSet]?.spellProjectile?.impact;
    if(!sprite)return;
    const life=sprite.frames/sprite.fps;
    effects.push({x:attack.projectile.x,y:attack.projectile.y,life,maxLife:life,sprite,
      scale:1.5+attack.charge*0.75});
  }

  function reflectProjectile(attack, reflector, direction, contact = null) {
    if(!attack.projectile)return false;
    const dir=normalize(direction),shot=attack.projectile;
    attack.dir={...dir};
    attack.reflectedOwnerId=reflector.id;
    attack.hitTargets=new Set();
    attack.selfCancelled=false;
    attack.clashed=false;
    shot.remainingLife=Math.max(0,(shot.remainingLife??6.7)*.5);
    if (shot.persistent) {
      renewProjectileContact(attack);
      shot.ownerId = reflector.id; shot.ownerTeam = reflector.team; shot.kickoffReady = false;
      setProjectileVelocity(attack, multiply(dir, shot.speed));
      if(shot.boomerang){Boomerang.resetRecall(shot,reflector.id);Boomerang.redirect(shot,dir);}
    }
    if(contact) {
      shot.x=contact.x+dir.x*(shot.radius+4);
      shot.y=contact.y+dir.y*(shot.radius+4);
    } else {
      const clearance=Math.abs(dir.x)*reflector.data.width/2+Math.abs(dir.y)*getBodyHeight(reflector)/2+shot.radius+4;
      shot.x=reflector.x+dir.x*clearance;
      shot.y=reflector.y+dir.y*clearance;
      burst(shot.x,shot.y,14,reflector.data.lightColor,5);
      sparkText(reflector.x,reflector.y-32,"REFLECT",reflector.data.lightColor);
    }
    enforceProjectileCap(reflector, 0);
    return true;
  }

  function resolveOwnedProjectileRicochet(a, b, time, shift,shiftY=0) {
    const av = multiply(a.attack.dir, a.shot.speed), bv = multiply(b.attack.dir, b.shot.speed);
    const offset = { x: b.shot.x + shift - a.shot.x + (bv.x - av.x) * time,
      y: b.shot.y + shiftY - a.shot.y + (bv.y - av.y) * time };
    const normal = length(offset) > .001 ? normalize(offset) : normalize({ x: av.x - bv.x, y: av.y - bv.y });
    const closing = dot({ x: av.x - bv.x, y: av.y - bv.y }, normal);
    if (closing <= .001) return false;
    const inverseA = 1 / a.shot.mass, inverseB = 1 / b.shot.mass;
    const impulse = 2 * closing / (inverseA + inverseB);
    for (const [entry, velocity, inverse, sign] of [[a, av, inverseA, -1], [b, bv, inverseB, 1]]) {
      entry.shot.x += velocity.x * time; entry.shot.y += velocity.y * time;
      const separation = Math.max(0, a.shot.radius + b.shot.radius + 1 - length(offset));
      entry.shot.x += normal.x * sign * separation * inverse / (inverseA + inverseB);
      entry.shot.y += normal.y * sign * separation * inverse / (inverseA + inverseB);
      setProjectileVelocity(entry.attack, { x: velocity.x + sign * impulse * inverse * normal.x,
        y: velocity.y + sign * impulse * inverse * normal.y });
      renewProjectileContact(entry.attack);
      if(entry.shot.boomerang)Boomerang.redirect(entry.shot,entry.attack.dir);
      entry.shot.clashCooldown = .12;
    }
    restoreAirDashesFromHit(a.owner);
    emitProjectileCue(a.attack, "clash");
    playAudioEvent("clash", { fighter: a.owner, intensity: .65 });
    if(hasFiredUpAudio(a.owner)||hasFiredUpAudio(b.owner))playAudioEvent("firedUpClash",{fighter:a.owner,intensity:.8});
    return true;
  }

  function resolveProjectileClashes(dt) {
    const movement = new Map();
    const entries = [];
    for (const shooter of fighters) for (const attack of shooter.projectiles) {
      const shot = attack.projectile;
      if (shot.removed) continue;
      shot.clashCooldown = Math.max(0, (shot.clashCooldown || 0) - dt);
      const owner = attack.reflectedOwnerId ? fighters.find(f => f.id === attack.reflectedOwnerId) : shooter;
      if (!owner || owner.koScored || isPhantomGhost(owner) || roundResetTimer > 0 || shot.clashCooldown > 0 || shot.remainingLife <= 0) continue;
      const next = { ...shot, x:shot.x+attack.dir.x*shot.speed*dt, y:shot.y+attack.dir.y*shot.speed*dt };
      const paths = wrapProjectile(next, shot);
      if(isUpperRecovering(next))continue;
      if (shot.persistent ? projectileTerrainContact(paths,shot.radius) : currentStage().terrain.some(rect => rect.kind !== "oneway" && paths.some(p =>
        segmentIntersectsRect(p.x1,p.y1,p.x2,p.y2,expandRect(getTerrainRect(rect),shot.radius))))) continue;
      entries.push({ attack, shot, owner });
    }
    for (let i=0;i<entries.length;i++) for(let j=i+1;j<entries.length;j++) {
      const a=entries[i],b=entries[j];
      const owned = a.owner === b.owner;
      if (movement.has(a.attack)||movement.has(b.attack)||a.shot.removed||b.shot.removed||
          (owned ? !a.shot.persistent || !b.shot.persistent : !canFightersAffect(a.owner,b.owner))) continue;
      const relative = {x:b.attack.dir.x*b.shot.speed-a.attack.dir.x*a.shot.speed,
        y:b.attack.dir.y*b.shot.speed-a.attack.dir.y*a.shot.speed};
      const span=currentStageWidth()+2*(currentStage().wrapMargin??a.shot.radius);
      const shifts=currentStage().triWrap?[-currentStageHeight(),0,currentStageHeight()].map(y=>({x:0,y})):
        (currentStage().wrap!==false&&!currentStage().edgePortals ? [-span,0,span] : [0]).map(x=>({x,y:0}));
      let contact=null,contactShift={x:0,y:0};
      for(const shift of shifts) {
        const offset={x:b.shot.x+shift.x-a.shot.x,y:b.shot.y+shift.y-a.shot.y};
        const speed2=dot(relative,relative);
        const t=speed2>0 ? clamp(-dot(offset,relative)/speed2,0,dt) : 0;
        if(Math.hypot(offset.x+relative.x*t,offset.y+relative.y*t)<=a.shot.radius+b.shot.radius) {
          const c=dot(offset,offset)-(a.shot.radius+b.shot.radius)**2,along=dot(offset,relative);
          contact=owned&&c>0&&speed2>0 ? clamp((-along-Math.sqrt(Math.max(0,along*along-speed2*c)))/speed2,0,dt) : t;
          contactShift=shift;break;
        }
      }
      if(contact===null) continue;
      if (owned) {
        if (resolveOwnedProjectileRicochet(a,b,contact,contactShift.x,contactShift.y)) {
          movement.set(a.attack,Math.max(0,dt-contact));movement.set(b.attack,Math.max(0,dt-contact));
        }
        continue;
      }
      const empowered=hasFiredUpAudio(a.owner)||hasFiredUpAudio(b.owner);
      buildFiredUp(a.owner,8);buildFiredUp(b.owner,8);
      for(const [entry,other] of [[a,b],[b,a]]) {
        entry.shot.x+=entry.attack.dir.x*entry.shot.speed*contact;
        entry.shot.y+=entry.attack.dir.y*entry.shot.speed*contact;
        entry.attack.dir=multiply(entry.attack.dir,-1);
        entry.attack.reflectedOwnerId=other.owner.id;
        entry.attack.doubleReflect=true;
        entry.attack.hitTargets=new Set();
        entry.shot.remainingLife=Math.max(0,(entry.shot.remainingLife??6.7)*.5);
        entry.shot.clashCooldown=0.12;
        if (entry.shot.persistent) {
          renewProjectileContact(entry.attack);
          entry.shot.ownerId=other.owner.id;entry.shot.ownerTeam=other.owner.team;entry.shot.kickoffReady=false;
          setProjectileVelocity(entry.attack,multiply(entry.attack.dir,entry.shot.speed));
          if(entry.shot.boomerang){Boomerang.resetRecall(entry.shot,other.owner.id);Boomerang.redirect(entry.shot,entry.attack.dir);}
        }
        movement.set(entry.attack,Math.max(0,dt-contact));
      }
      for (const owner of [a.owner,b.owner]) enforceProjectileCap(owner,0);
      burst(a.shot.x,a.shot.y,18,"#ffe393",6);
      sparkText(a.shot.x,a.shot.y-28,"DOUBLE REFLECT","#ffe393");
      playAudioEvent("clash",{fighter:a.owner,intensity:0.85});
      if(empowered)playAudioEvent("firedUpClash",{fighter:a.owner,intensity:1});
    }
    return movement;
  }

  function findProjectilePunchContact(paths, punchBox, radius) {
    for (const path of paths) {
      const steps = Math.max(1, Math.ceil(Math.hypot(path.x2 - path.x1, path.y2 - path.y1) / Math.max(4, radius)));
      for (let step = 0; step <= steps; step += 1) {
        const x = lerp(path.x1, path.x2, step / steps);
        const y = lerp(path.y1, path.y2, step / steps);
        if (attackHitboxOverlapsRect(openSoccerRect(punchBox,x,y), { x: x - radius, y: y - radius, w: radius * 2, h: radius * 2 })) return { x, y };
      }
    }
    return null;
  }

  function wrapProjectile(shot, previous) {
    const stage = currentStage();
    if(stage.triWrap){
      const paths=Dashball.objectives.verticalPaths(previous,shot,stage.height),end=paths.at(-1);
      if(end){shot.x=end.x2;shot.y=end.y2;}return paths;
    }
    if(stage.openSoccer){
      const path={x1:previous.x,y1:previous.y,x2:shot.x,y2:shot.y};
      Dashball.openSoccer.wrap(shot,stage,shot.radius);
      if(dashballState&&(Dashball.openSoccer.recover(dashballState,dashballWorld(0),shot,shot.radius)||isUpperRecovering(shot)))return [];
      return [-stage.width,0,stage.width].map(dx=>({...path,x1:path.x1+dx,x2:path.x2+dx}));
    }
    const paths = [{ x1: previous.x, y1: previous.y, x2: shot.x, y2: shot.y }];
    if (stage.edgePortals) {
      const before = { x: shot.x, y: shot.y };
      warpOffsetEntity(shot, shot.radius, shot.radius);
      const dx = shot.x - before.x;
      const dy = shot.y - before.y;
      if (dx || dy) paths.push({ x1: previous.x + dx, y1: previous.y + dy, x2: shot.x, y2: shot.y });
      return paths;
    }
    const shift = (dx, dy) => {
      const copies = paths.map((path) => ({ x1: path.x1 + dx, y1: path.y1 + dy, x2: path.x2 + dx, y2: path.y2 + dy }));
      paths.push(...copies);
      shot.x += dx;
      shot.y += dy;
    };
    if (stage.wrap !== false) {
      const margin = stage.wrapMargin ?? shot.radius;
      const span = currentStageWidth() + margin * 2;
      if (shot.x < -margin) shift(span, 0);
      else if (shot.x > currentStageWidth() + margin) shift(-span, 0);
    }
    const hole = stage.hole;
    const holeLane = hole && shot.x > hole.x + shot.radius * 0.5 && shot.x < hole.x + hole.width - shot.radius * 0.5;
    if (stage.verticalWrap || holeLane) {
      const margin = stage.verticalWrap ? (stage.verticalWrapMargin ?? 48) : 48;
      if (shot.y - shot.radius > currentStageHeight() + margin) shift(0, -shot.radius - shot.y);
      else if (!hole?.bottomOnly&&shot.y + shot.radius < -margin) shift(0, currentStageHeight() + shot.radius - shot.y);
    }
    return paths;
  }

  function updateActivePunchAim(fighter, dt) {
    if (fighter.attack?.projectile) return;
    if (!isAttackActive(fighter) || !fighter.hasLiveAim || length(fighter.aim) <= 0.12) {
      return;
    }

    const current = normalize(fighter.attack.dir);
    const target = normalize(fighter.aim);
    const currentAngle = Math.atan2(current.y, current.x);
    const targetAngle = Math.atan2(target.y, target.x);
    const angleDelta = normalizeAngle(targetAngle - currentAngle);
    const maxTurn = fighter.data.punchActiveTurnRate * dt;
    const nextAngle = currentAngle + clamp(angleDelta, -maxTurn, maxTurn);
    fighter.attack.dir = { x: Math.cos(nextAngle), y: Math.sin(nextAngle) };
  }

  function updateSpotDodgeState(fighter) {
    if (fighter.spotDodgePendingWhiff && fighter.spotDodgeInvuln <= 0) {
    fighter.spotDodgePendingWhiff = false;
    fighter.spotDodgeMissFlash = SPOT_DODGE_MISS_FLASH_TIME;
    setJuked(fighter, JUKE_DEFENDER_WHIFF_DURATION, "JUKED");
    fighter.spotDodgeRecovery = Math.max(fighter.spotDodgeRecovery, SPOT_DODGE_WHIFF_RECOVERY);
    fighter.forceCrouch = Math.max(fighter.forceCrouch, SPOT_DODGE_WHIFF_RECOVERY + 0.08);
    fighter.vx *= 0.2;
    playAudioEvent("spotDodgeMiss", { fighter, intensity: 0.7 });
    sparkText(fighter.x, fighter.y - 58, "EMPTY", "#d7d2c8");
  }
  }

  function updateComboResilienceMeters(fighter, dt) {
    const inComboPressure = isTrueComboPressure(fighter);
    if (inComboPressure) {
      fighter.comboMeterRetention = fighter.data.meterRetentionDelay;
      updateHardDefenseRecharge(fighter, dt);
      updateAirDashBank(fighter, dt);
      return;
    }

    if (fighter.dashReboundBreakerRechargeTimer > 0 && fighter.comboHits > 0 && fighter.hitstun > 0) {
      const rechargeDt = Math.min(dt, fighter.dashReboundBreakerRechargeTimer);
      fighter.dashReboundBreakerRechargeTimer = Math.max(0, fighter.dashReboundBreakerRechargeTimer - dt);
      fighter.comboMeterRetention = Math.max(fighter.comboMeterRetention, fighter.data.meterRetentionDelay);
      updateHardDefenseRecharge(fighter, rechargeDt * DASH_REBOUND_BREAKER_RECHARGE_RATE_MULT);
      return;
    }

    if (fighter.dashReboundBreakerRechargeTimer > 0) {
      fighter.dashReboundBreakerRechargeTimer = 0;
    }

    if (fighter.comboMeterRetention > 0) {
      fighter.comboMeterRetention = Math.max(0, fighter.comboMeterRetention - dt);
      return;
    }

  }

  function updateGroundDefenseRefill(fighter, dt) {
    if (
      !fighter.defenseGroundRefillPending ||
      fighter.comboHits > 0 ||
      fighter.hitstun > 0 ||
      !fighter.onGround
    ) {
      fighter.defenseGroundRefillTimer = 0;
      return;
    }

    fighter.defenseGroundRefillTimer += dt;
    if (fighter.defenseGroundRefillTimer >= GROUND_DEFENSE_REFILL_SETTLE_TIME) {
      resetDefensiveResources(fighter);
      fighter.restoreFlash = RESOURCE_RESTORE_FLASH_TIME;
      fighter.restoreFlashType = "ground";
      sparkText(fighter.x, fighter.y - 70, "DEFENSE BACK", fighter.data.lightColor);
    }
  }

  function isTrueComboPressure(fighter) {
    return (
      fighter.hitstun > 0 &&
      fighter.comboHits > 0 &&
      fighter.lastAttacker &&
      fighter.floorTechVulnerable <= 0 &&
      fighter.knockdownTimer <= 0 &&
      !COMBO_BREAKER_BLOCKED_STUN_TYPES.has(fighter.stunType)
    );
  }

  function isComboKnockdownPressure(fighter) {
    return (
      fighter.hitstun > 0 &&
      fighter.comboHits > 0 &&
      fighter.lastAttacker &&
      fighter.floorTechVulnerable <= 0 &&
      fighter.stunType === "knockdown" &&
      fighter.knockdownTimer > 0
    );
  }

  function canUseParryCommand(fighter) {
    return (!fighter.electricLatch || fighter.electricLatch.remaining === 3) &&
      (isTrueComboPressure(fighter) || isComboKnockdownPressure(fighter));
  }

  function canUseComboBreaker(fighter) {
    return (!fighter.electricLatch || fighter.electricLatch.remaining === 3) && isTrueComboPressure(fighter);
  }

  function updateHardDefenseRecharge(fighter, dt) {
    const nextResource = fighter.resourceSpentOrder.find((resource) => {
      return resource === "dash" ? !fighter.escapeAvailable : !fighter.punchParryAvailable;
    });
    if (!nextResource) {
      return;
    }

    if (nextResource === "dash") {
      fighter.dashEscapeMeter = Math.min(1, fighter.dashEscapeMeter + fighter.data.dashEscapeRechargeRate * dt);
      if (fighter.dashEscapeMeter >= 1) {
        restoreDashEscape(fighter);
      }
    } else if (nextResource === "punch") {
      fighter.punchParryMeter = Math.min(1, fighter.punchParryMeter + fighter.data.punchParryRechargeRate * dt);
      if (fighter.punchParryMeter >= 1) {
        restorePunchParry(fighter);
      }
    }

    fighter.resourceSpentOrder = fighter.resourceSpentOrder.filter((resource) => {
      return resource === "dash" ? !fighter.escapeAvailable : !fighter.punchParryAvailable;
    });
  }

  function updateAirDashBank(fighter, dt) {
    if(fighter.data.phantomDash)return;
    if (fighter.bankedAirDashes >= fighter.data.maxAirDashes) {
      fighter.airDashRechargeMeter = 1;
      return;
    }

    fighter.airDashRechargeMeter += fighter.data.airDashRechargeRate * dt;
    while (fighter.airDashRechargeMeter >= 1 && fighter.bankedAirDashes < fighter.data.maxAirDashes) {
      fighter.airDashRechargeMeter -= 1;
      fighter.bankedAirDashes += 1;
      fighter.restoreFlash = RESOURCE_RESTORE_FLASH_TIME * 0.55;
      fighter.restoreFlashType = "air";
    }
  }

  function spendDefensiveResource(fighter, resource) {
    if (resource === "dash") {
      fighter.escapeAvailable = false;
      fighter.dashEscapeMeter = 0;
    } else if (resource === "punch") {
      fighter.punchParryAvailable = false;
      fighter.punchParryMeter = 0;
    }

    fighter.resourceSpentOrder = fighter.resourceSpentOrder.filter((existing) => existing !== resource);
    fighter.resourceSpentOrder.push(resource);
    fighter.defenseGroundRefillPending = true;
    fighter.defenseGroundRefillTimer = 0;
    fighter.resourceFlash = Math.max(fighter.resourceFlash, 0.16);
  }

  function restoreDashEscape(fighter) {
    fighter.escapeAvailable = true;
    fighter.dashEscapeMeter = 1;
    fighter.defenseGroundRefillPending = !fighter.punchParryAvailable;
    fighter.restoreFlash = RESOURCE_RESTORE_FLASH_TIME;
    fighter.restoreFlashType = "dash";
    sparkText(fighter.x, fighter.y - 70, "DASH BACK", fighter.data.lightColor);
  }

  function restorePunchParry(fighter) {
    fighter.punchParryAvailable = true;
    fighter.punchParryMeter = 1;
    fighter.defenseGroundRefillPending = !fighter.escapeAvailable;
    fighter.restoreFlash = RESOURCE_RESTORE_FLASH_TIME;
    fighter.restoreFlashType = "punch";
    sparkText(fighter.x, fighter.y - 70, "PARRY BACK", "#f7e27a");
  }

  function releaseBankedAirDashes(fighter) {
    if(fighter.data.phantomDash)return;
    if (fighter.bankedAirDashes <= 0) {
      return;
    }

    fighter.airDashes = Math.min(fighter.data.maxAirDashes, Math.max(fighter.airDashes, fighter.bankedAirDashes));
    fighter.bankedAirDashes = 0;
    fighter.airDashRechargeMeter = 0;
    fighter.restoreFlash = RESOURCE_RESTORE_FLASH_TIME * 0.75;
    fighter.restoreFlashType = "air";
  }

  function restoreAirDashesFromHit(attacker) {
    if(attacker.data.phantomDash&&!attacker.attack?.materialization)return;
    attacker.airDashes = attacker.data.maxAirDashes;
    clearMercyDash(attacker);
  }

  function confirmHit(attacker) {
    const attack = attacker.attack;

    restoreAirDashesFromHit(attacker);
    attacker.whiffLag = 0;
    attacker.punchLockout = 0;
    attacker.cancelFlash = Math.max(attacker.cancelFlash, 0.2);

    if (attack) {
      if(attacker.data.spear){attack.confirmed=true;return;}
      if(attacker.data.automaticSequence&&attack.sequenceStage!==undefined){attack.confirmed=true;return;}
      if (attack.projectile?.persistent) {
        attacker.attack = null;
        return;
      }
      attacker.punchVisual = { dir: { ...attack.dir }, charge: attack.charge, age: 0, swordPhase: attack.swordPhase || 0 };
      if(attack.sequenceStage!==undefined){
        Object.assign(attacker.punchVisual,{sequenceStage:attack.sequenceStage,sequenceAge:attack.age,sequenceTiming:getSequenceTiming(attacker.data.punchSequence[attack.sequenceStage],attack.startup)});
        if(attack.actionSpeed)Object.assign(attacker.punchVisual.sequenceTiming,{active:attack.active,recovery:attack.recovery,total:attack.total,cancelAt:attacker.edgebertChain.cancelAt});
      }
      attack.selfCancelled = true;
      attack.active = 0;
      attack.recovery = 0;
      attack.total = attack.age;
      attacker.attack = attacker.data.swordPunch && !attack.projectile && !attack.electricTick && !attack.swordPhase ? createSwordFollowup(attack, true) : null;
    }
  }

  function createSwordFollowup(attack, priorHit = false) {
    const speed=attack.actionSpeed||1;
    const startup = 0.11/speed;
    const active = (0.16 + attack.charge * 0.1)/speed;
    const recovery = 0.2/speed;
    return {
      ...attack, id: ++attackSerial, age: 0, swordPhase: 1, priorHit,
      startup, active, recovery, total: startup + active + recovery,
      dir: { ...attack.dir }, hitTargets: new Set(), clashed: false, selfCancelled: false,
    };
  }

  function createSequenceFollowup(fighter,attack){
    const stage=attack.sequenceStage+1,timing=getSequenceTiming(fighter.data.punchSequence[stage]),speed=attack.actionSpeed||1;
    for(const key of Object.keys(timing))timing[key]/=speed;
    const next={...attack,...timing,id:++attackSerial,age:Math.max(0,attack.age-attack.total),sequenceStage:stage,
      priorHit:attack.priorHit||attack.hitTargets.size>0,confirmed:false,hitTargets:new Set(),clashed:false,selfCancelled:false,
      fromShieldRelease:false,shieldParryTriggered:false,dir:{...attack.dir}};
    fighter.edgebertChain={stage,age:next.age,dir:{...next.dir},...timing};
    playAudioEvent("punchSwing",{fighter,charge:attack.charge,sequenceStage:stage,intensity:stage<2?.5:.85});return next;
  }

  function cancelAttackIntoRecovery(attacker, attack, lagScale = 1) {
    if (!attack || attacker.attack !== attack) {
      return;
    }
    resetPunchSequence(attacker);

    const recovery = attacker.data.noWhiffPenalty
      ? attacker.data.punchRecovery * (1 + attack.charge * 0.22)
      : attacker.data.punchSequence?Math.max(attack.recovery,getPunchProfile(attacker,attack).punchBlockRecovery||0):attack.recovery;
    const recoveryLag = Math.max(0.06, recovery * lagScale);
    if (attack.projectile?.persistent) {
      attacker.attack = null;
      attacker.whiffLag = Math.max(attacker.whiffLag, recoveryLag);
      attacker.punchLockout = Math.max(attacker.punchLockout, recoveryLag);
      return;
    }
    attack.selfCancelled = true;
    attack.active = 0;
    attack.total = attack.age;
    attacker.attack = null;
    attacker.whiffLag = Math.max(attacker.whiffLag, recoveryLag);
    attacker.punchLockout = Math.max(attacker.punchLockout, recoveryLag);
  }

  function updateMercyDash(fighter, dt) {
    if (!canBuildMercyDash(fighter)) {
      if (fighter.onGround || fighter.wallSliding || fighter.airDashes > 0 || fighter.hitstun > 0 || fighter.floorTechVulnerable > 0) {
        fighter.mercyDashTimer = 0;
      }
      return;
    }

    fighter.mercyDashTimer += dt;
    if (fighter.mercyDashTimer < fighter.data.mercyDashDelay) {
      return;
    }

    fighter.airDashes = 1;
    fighter.hasMercyDash = true;
    fighter.mercyDashTimer = 0;
    fighter.mercyDashFlash = 0.32;
    fighter.flash = Math.max(fighter.flash, 0.1);
    sparkText(fighter.x, fighter.y - 58, "MERCY", fighter.data.lightColor);
    burst(fighter.x, fighter.y, 12, fighter.data.lightColor, 3.8);
  }

  function canBuildMercyDash(fighter) {
    return (
      !fighter.data.phantomDash &&
      !fighter.onGround &&
      !fighter.wallSliding &&
      fighter.airDashes <= 0 &&
      fighter.mercyDashWrapped &&
      !fighter.hasMercyDash &&
      fighter.hitstun <= 0 &&
      fighter.hitstop <= 0 &&
      fighter.floorTechVulnerable <= 0 &&
      roundResetTimer <= 0
    );
  }

  function clearMercyDash(fighter) {
    fighter.hasMercyDash = false;
    fighter.mercyDashTimer = 0;
    fighter.mercyDashWrapped = false;
    fighter.mercyDashFlash = 0;
  }

  function updateTumble(fighter, dt) {
    const stunned = fighter.hitstun > 0 || fighter.hitstop > 0;
    const angularDrag = stunned ? 0.965 : 0.82;

    fighter.angle += fighter.angularVelocity * dt;
    fighter.angularVelocity *= Math.pow(angularDrag, dt * 60);

    if (!stunned) {
      fighter.angle *= Math.pow(fighter.onGround ? 0.62 : 0.9, dt * 60);
    }

    fighter.angle = normalizeAngle(fighter.angle);

    if (Math.abs(fighter.angle) < 0.004 && Math.abs(fighter.angularVelocity) < 0.025) {
      fighter.angle = 0;
      fighter.angularVelocity = 0;
    }
  }

  function applyTumble(fighter, direction, strength) {
    const dir = length(direction) > 0 ? normalize(direction) : { x: gameplayRandom() < 0.5 ? -1 : 1, y: 0 };
    const sign = Math.abs(dir.x) > 0.1 ? Math.sign(dir.x) : Math.sign(dir.y || 1);
    fighter.angularVelocity = sign * strength * (0.8 + gameplayRandom() * 0.45);
    fighter.angle += sign * 0.08;
  }

  function releaseDash(fighter, direction, chargeTime,committed=false) {
    if (fighter.punchBlockstun > 0 || fighter.shieldPressureRearm) return;
    const data = fighter.data;
    if(data.phantomDash&&!fighter.onGround){beginPhantomDash(fighter,direction,chargeTime);return;}
    if(data.boomerang&&!committed){
      resetGroundRun(fighter,true);
      if(!fighter.heavyDashWindup&&!(fighter.heavyDashRecovery>0))fighter.heavyDashWindup={dir:{...direction},charge:chargeTime,remaining:data.dashStartup};
      fighter.dashPending=false;fighter.chargingDash=false;fighter.dashHoldTimer=0;fighter.dashCharge=0;fighter.dashChargeAirborne=false;
      return;
    }
    const inAir = !fighter.onGround && !fighter.wallSliding;
    const usingMercyDash = inAir && fighter.hasMercyDash && fighter.airDashes <= 1;
    const wallBoost = getWallLaunchBoost(fighter, direction);

    if (inAir && fighter.airDashes <= 0) {
      fighter.dashPending = false;
      fighter.dashHoldTimer = 0;
      fighter.chargingDash = false;
      fighter.dashChargeAirborne = false;
      fighter.airBrakeOnly = false;
      fighter.dashCharge = 0;
      sparkText(fighter.x, fighter.y - 48, "EMPTY", "#d7d2c8");
      return;
    }

    const fromShield = isShielding(fighter);
    if(Sports?.isBattle(dashballState||sandbagState)&&fighter.dashballSpawnProtected){fighter.invulnerable=0;delete fighter.dashballSpawnProtected;}
    if(sandbagState)fighter.sandbagDashSerial=++attackSerial;
    const rawDir = length(direction) > 0 ? normalize(direction) : { ...fighter.face };
    const dashChargeRatio = clamp(chargeTime / data.dashChargeTime, 0, 1);
    const tippySuperJump = fighter.tippyDashQueued && fighter.tippyToes && !inAir && !fighter.wallSliding &&
      fighter.hasLiveAim && dot(rawDir, gravityVector()) < -TIPPY_TOES_INPUT_DOT;
    const takeoffContact = fighter.onGround ? groundFeedbackContact(fighter) : null;
    const iceTakeoff=(data.ice||data.ember)&&fighter.onGround?iceSupport(fighter):null;
    const jumpDirection = tippySuperJump ? getTippySuperJumpDirection(rawDir, dashChargeRatio) : rawDir;
    const dir = jumpDirection;
    const speed = (tippySuperJump ? getTippySuperJumpSpeed(fighter, dashChargeRatio) : getDashSpeed(fighter, chargeTime, inAir)) * wallBoost;

    if (inAir) {
      if (!data.unlimitedAirDashes) fighter.airDashes -= 1;
      fighter.airSteerTimer = data.airSteerDuration;
      fighter.airSteerDuration = data.airSteerDuration;
      fighter.airSteerSpeed = speed;
      if (usingMercyDash) {
        clearMercyDash(fighter);
      }
    } else {
      fighter.airSteerTimer = 0;
      fighter.airSteerDuration = 0;
      fighter.airSteerSpeed = 0;
      fighter.groundSkidTimer = Math.max(fighter.groundSkidTimer, tippySuperJump?GROUND_DASH_SKID_TIME:(data.groundDashSkidTime??GROUND_DASH_SKID_TIME));
    }

    const velocity = tippySuperJump
      ? getTippySuperJumpVelocity(fighter, rawDir, speed, dashChargeRatio)
      : getCarriedDashVelocity(fighter, dir, speed, inAir);
    // A running jump keeps its real takeoff momentum, not a banked speed bonus.
    if(!inAir&&fighter.runJumpCarry&&dot(rawDir,gravityVector())<-TIPPY_TOES_INPUT_DOT){
      const g=gravityVector(),t={x:g.y,y:-g.x},side=dot({x:fighter.vx,y:fighter.vy},t),next=dot(velocity,t);
      if(Math.abs(side)>Math.abs(next)&&side*next>=0){velocity.x+=t.x*(side-next);velocity.y+=t.y*(side-next);}
    }
    resetGroundRun(fighter,true);
    fighter.vx = velocity.x;
    fighter.vy = velocity.y;
    if(data.airFloat?.dashDrag){
      if(inAir)fighter.floatMotion="self";
      else delete fighter.floatMotion;
    }
    if(data.airDashArc) {
      delete fighter.airDashArc;
      if(inAir&&!usingMercyDash)beginAirArc(fighter,dir,speed);
    }
    fighter.dashWeaveAge = 0;
    fighter.dashWeaveSign *= -1;
    fighter.onGround = false;
    fighter.touchingWall = false;
    fighter.wallSliding = false;
    fighter.wallClinging = false;
    fighter.dashParry = data.dashParryWindow;
    fighter.dashDir = { ...dir };
    fighter.face = { ...dir };
    fighter.dashPending = false;
    fighter.dashHoldTimer = 0;
    fighter.chargingDash = false;
    fighter.dashChargeAirborne = false;
    fighter.airBrakeOnly = false;
    fighter.dashCharge = 0;
    fighter.dashChargeAge = 0;
    fighter.fullDashChargeHold = 0;
    fighter.tippyDashQueued = false;
    fighter.dashCarryTimer = inAir || tippySuperJump ? AIR_DASH_CARRY_TIME : 0;
    if(inAir&&data.ember)fighter.dashCarryTimer=data.airDashCarryTime;
    if(fighter.airDashArc)fighter.dashCarryTimer=fighter.airDashArc.duration;
    if(dashballState?.sticky&&dashballState.ball.carrier===fighter.id){
      fighter.stickyDashPenalty=.55;
      if(inAir){const duration=.6/.55;fighter.dashCarryTimer*=duration;fighter.airSteerTimer*=duration;fighter.airSteerDuration*=duration;
        if(fighter.airDashArc)fighter.airDashArc.duration*=duration;}
    }
    fighter.punchPursuitActive = false;
    fighter.lastDashCharge = dashChargeRatio;
    consumeWallLaunch(fighter, wallBoost);
    if (fromShield) {
      startDashFromShield(fighter);
    }
    if (tippySuperJump) {
      fighter.tippyJumpTimer = TIPPY_SUPER_JUMP_CAP_TIME + dashChargeRatio * 0.16;
      fighter.tippyJumpSpeedCap = Math.max(fighter.tippyJumpSpeedCap, Math.hypot(velocity.x, velocity.y) * 1.05);
      fighter.airSteerTimer = Math.max(fighter.airSteerTimer, data.airSteerDuration * 0.55);
      fighter.airSteerDuration = Math.max(fighter.airSteerDuration, data.airSteerDuration * 0.75);
      fighter.airSteerSpeed = Math.max(fighter.airSteerSpeed, speed * 0.62);
      fighter.cancelFlash = Math.max(fighter.cancelFlash, 0.18);
      sparkText(fighter.x, fighter.y - 64, "SUPER JUMP", data.lightColor);
    }

    burst(
      fighter.x - dir.x * 16,
      fighter.y - dir.y * 16,
      tippySuperJump ? 26 : wallBoost > 1 ? 24 : 12,
      data.lightColor,
      speed * (tippySuperJump ? 0.012 : 0.018)
    );
    playDashAudio(fighter, chargeTime, speed, wallBoost, tippySuperJump);
    if(takeoffContact)emitTakeoffFeedback(fighter,takeoffContact,tippySuperJump);
    if(data.ice){
      if(inAir){Ice.finishAir(fighter.ice,normalizeIcePoint);Ice.startAir(fighter.ice,iceTrailPoint(fighter),fighter.dashCarryTimer);}
      else if(iceTakeoff&&!tippySuperJump)Ice.startGround(fighter.ice,iceTakeoff,stageGravityAxis,stageGravitySign,iceSurfaceAlong(fighter,iceTakeoff),data.width*.45);
    }
    if(data.ember){
      fighter.ember.trail=null;
      if(inAir)Ember.start(fighter.ember,{x:fighter.x,y:fighter.y},fighter.dashCarryTimer);
      else if(iceTakeoff&&!tippySuperJump)Ember.start(fighter.ember,{x:takeoffContact.x,y:takeoffContact.y},fighter.groundSkidTimer,
        {id:iceTakeoff.id,axis:stageGravityAxis,sign:stageGravitySign});
    }
  }

  function getTippySuperJumpDirection(rawDir, charge) {
    const gravity = gravityVector();
    const along = dot(rawDir, gravity);
    return normalize({
      x: -gravity.x + (rawDir.x - gravity.x * along) * getTippySuperJumpHorizontalScale(charge),
      y: -gravity.y + (rawDir.y - gravity.y * along) * getTippySuperJumpHorizontalScale(charge),
    });
  }

  function getTippySuperJumpSpeed(fighter, charge) {
    return lerp(TIPPY_SUPER_JUMP_BASE_SPEED, TIPPY_SUPER_JUMP_MAX_SPEED, easeOutQuad(charge)) * (fighter.data.tippyJumpScale || 1);
  }

  function getTippySuperJumpVelocity(fighter, rawDir, speed, charge) {
    const gravity = gravityVector();
    const inputAlong = dot(rawDir, gravity);
    const momentumAlong = fighter.vx * gravity.x + fighter.vy * gravity.y;
    return {
      x: -gravity.x * speed + (fighter.vx - gravity.x * momentumAlong) * 0.18 + (rawDir.x - gravity.x * inputAlong) * speed * getTippySuperJumpHorizontalScale(charge),
      y: -gravity.y * speed + (fighter.vy - gravity.y * momentumAlong) * 0.18 + (rawDir.y - gravity.y * inputAlong) * speed * getTippySuperJumpHorizontalScale(charge),
    };
  }

  function getTippySuperJumpHorizontalScale(charge) {
    return TIPPY_SUPER_JUMP_HORIZONTAL_SCALE + charge * TIPPY_SUPER_JUMP_CHARGED_HORIZONTAL_SCALE;
  }

  function getCarriedDashVelocity(fighter, dir, speed, inAir) {
    const current = { x: fighter.vx, y: fighter.vy };
    const forwardSpeed = dot(current, dir);
    const lateral = {
      x: current.x - dir.x * forwardSpeed,
      y: current.y - dir.y * forwardSpeed,
    };
    if(inAir&&fighter.data.airFloat?.dashDrag){
      const carry=fighter.data.airFloat.dashLateralCarry;
      const lateralSpeed=length(lateral),kept=Math.min(lateralSpeed*carry,speed*carry);
      const scale=lateralSpeed>0?kept/lateralSpeed:0;
      return {x:dir.x*speed+lateral.x*scale,y:dir.y*speed+lateral.y*scale};
    }
    const sameDirectionInherit = inAir ? AIR_DASH_SAME_DIRECTION_INHERIT : DASH_SAME_DIRECTION_INHERIT;
    const lateralCarry = inAir ? AIR_DASH_LATERAL_CARRY : DASH_LATERAL_CARRY;
    let targetSpeed = speed;

    if (forwardSpeed > 0) {
      targetSpeed += Math.min(forwardSpeed * sameDirectionInherit, speed * DASH_SAME_DIRECTION_CAP);
    } else if (forwardSpeed < 0) {
      const reversePenalty = clamp(-forwardSpeed / Math.max(speed, 1), 0, 1) * DASH_REVERSE_SPEED_PENALTY;
      targetSpeed *= 1 - reversePenalty;
    }

    return {
      x: dir.x * targetSpeed + lateral.x * lateralCarry,
      y: dir.y * targetSpeed + lateral.y * lateralCarry,
    };
  }

  function getWallLaunchBoost(fighter, direction) {
    if (!fighter.wallSliding || fighter.wallLaunchBoost <= 1 || fighter.wallNormalX === 0) {
      return 1;
    }

    const dir = length(direction) > 0 ? normalize(direction) : { ...fighter.face };
    return dir.x * fighter.wallNormalX > 0.3 ? fighter.wallLaunchBoost : 1;
  }

  function consumeWallLaunch(fighter, wallBoost) {
    if (fighter.wallSliding || wallBoost > 1) {
      fighter.wallLaunchBoost = 1;
    }
  }

  function getDashSpeed(fighter, chargeTime, inAir = !fighter.onGround && !fighter.wallSliding) {
    const data = fighter.data;
    const charge = clamp(chargeTime / data.dashChargeTime, 0, 1);
    let curved = easeOutQuad(charge);

    if (inAir) {
      curved = clamp(0.32 + curved * 0.58, 0, 0.9);
    }

    const mercyScale = inAir && fighter.hasMercyDash && fighter.airDashes <= 1 ? data.mercyDashScale : 1;
    const groundScale = inAir ? 1 : data.groundDashLaunchMult;
    const base=inAir?data.airDashBase??data.dashBase:data.dashBase,max=inAir?data.airDashMax??data.dashMax:data.dashMax;
    return lerp(base, max, curved) * (inAir ? data.airDashScale : groundScale) * mercyScale * fighterStatusScale(fighter,"movement")*
      (dashballState?.sticky&&dashballState.ball.carrier===fighter.id ? .55 : 1);
  }

  function syncStickyMobility(fighter,carrying){
    if(!dashballState?.sticky)return;
    const scale=carrying ? .55 : 1,old=fighter.stickyDashPenalty??1;
    if(scale===old)return;
    if(isDashMovementActive(fighter)&&fighter.hitstun<=0){
      const ratio=scale/old;fighter.vx*=ratio;fighter.vy*=ratio;
      if(fighter.airDashArc){fighter.airDashArc.speed*=ratio;fighter.airDashArc.cruiseSpeed*=ratio;}
      if(fighter.airSteerTimer>0){
        const time=carrying ? .6/.55 : .55/.6;fighter.airSteerTimer*=time;fighter.airSteerDuration*=time;fighter.dashCarryTimer*=time;
        if(fighter.airDashArc){fighter.airDashArc.duration*=time;fighter.airDashArc.age*=time;}
      }
    }
    fighter.stickyDashPenalty=scale;
  }

  function getAirDashChargeGravityScale(fighter, fullyCharged) {
    if (!fullyCharged) {
      const t = clamp(fighter.dashChargeAge / AIR_DASH_HOVER_GRACE, 0, 1);
      return lerp(AIR_DASH_INITIAL_GRAVITY_SCALE, AIR_DASH_LATE_GRAVITY_SCALE, easeOutQuad(t));
    }

    const t = clamp(fighter.fullDashChargeHold / AIR_DASH_FULL_DECAY_TIME, 0, 1);
    return lerp(AIR_DASH_FULL_INITIAL_GRAVITY_SCALE, AIR_DASH_FULL_LATE_GRAVITY_SCALE, easeOutQuad(t));
  }

  function applyTerminalVelocity(fighter, juggling) {
    let cap = juggling ? fighter.data.juggleTerminalVelocity : fighter.data.terminalVelocity;
    if (fighter.tippyJumpTimer > 0) {
      cap = Math.max(cap, fighter.tippyJumpSpeedCap || 0);
    }
    fighter.vy = clamp(fighter.vy, -cap, cap);
    if (stageGravityAxis === "x") fighter.vx = clamp(fighter.vx, -cap, cap);
  }

  function isAirDashCharging(fighter) {
    return (
      (fighter.airBrakeOnly || (fighter.chargingDash && fighter.dashChargeAirborne)) &&
      !fighter.onGround &&
      !fighter.wallSliding
    );
  }

  function applyAirDashChargeHover(fighter, dt, fullyCharged) {
    if (!isAirDashCharging(fighter)) {
      return;
    }

    fighter.airSteerTimer = 0;
    fighter.airSteerDuration = 0;
    fighter.airSteerSpeed = 0;

    const t = clamp(fighter.dashChargeAge / AIR_DASH_HOVER_GRACE, 0, 1);
    const brakeBase = fullyCharged ? AIR_DASH_LATE_BRAKE : lerp(AIR_DASH_INITIAL_BRAKE, AIR_DASH_LATE_BRAKE, t);
    const brake = Math.pow(brakeBase, dt * 60);
    fighter.vx *= brake;
    fighter.vy *= brake;

    if (fullyCharged) {
      const fallT = clamp(fighter.fullDashChargeHold / AIR_DASH_FULL_DECAY_TIME, 0, 1);
      let fallSpeed = lerp(AIR_DASH_FULL_FALL_SPEED, AIR_DASH_FULL_LATE_FALL_SPEED, easeOutQuad(fallT));
      if (fighter.data.airFloat) {
        fallSpeed *= fighter.data.airFloat.chargeFallScale * lerp(1, fighter.data.airFloat.upGravityScale, getAirFloatUpInput(fighter));
      }
      if (fighter.vy * stageGravitySign > fallSpeed) {
        if (stageGravityAxis === "y") fighter.vy = fallSpeed * stageGravitySign;
      }
      if (stageGravityAxis === "x" && fighter.vx * stageGravitySign > fallSpeed) fighter.vx = fallSpeed * stageGravitySign;
    }
  }

  function isAirArcActive(fighter) {
    const arc=fighter.airDashArc,gravity=gravityVector();
    return Boolean(arc&&fighter.data.airDashArc&&arc.age<arc.duration&&fighter.airSteerTimer>0&&
      !fighter.onGround&&!fighter.wallSliding&&!fighter.chargingDash&&!fighter.airBrakeOnly&&!fighter.koScored&&
      fighter.hitstun<=0&&fighter.punchBlockstun<=0&&fighter.dashReboundFlash<=0&&fighter.mutualDashReboundFlash<=0&&
      fighter.clashLostTimer<=0&&arc.gravityX===gravity.x&&arc.gravityY===gravity.y);
  }

  function beginAirArc(fighter,dir,speed) {
    const tuning=fighter.data.airDashArc,gravity=gravityVector(),right={x:gravity.y,y:-gravity.x};
    const input=clamp(-dot(dir,gravity),-1,1),arcSpeed=speed*tuning.speedScale;
    const rise=input>0 ? lerp(tuning.neutralRise,tuning.highRise,input) : lerp(tuning.neutralRise,tuning.lowRise,-input);
    const tangent=(fighter.vx*right.x+fighter.vy*right.y)*tuning.speedScale;
    const vertical=-arcSpeed*rise;
    fighter.airDashArc={age:0,duration:AIR_DASH_CARRY_TIME*tuning.durationScale,speed:arcSpeed,
      heading:tangent/Math.max(1,arcSpeed),rise,phaseBias:input>0?-input*tuning.upPhaseBias:-input*tuning.downPhaseBias,
      gravityX:gravity.x,gravityY:gravity.y};
    fighter.vx=right.x*tangent+gravity.x*vertical;fighter.vy=right.y*tangent+gravity.y*vertical;
    if(tuning.freeSteering)Object.assign(fighter.airDashArc,{angle:Math.atan2(fighter.vy,fighter.vx),cruiseSpeed:Math.hypot(fighter.vx,fighter.vy)});
    fighter.airSteerTimer=fighter.airDashArc.duration;fighter.airSteerDuration=fighter.airDashArc.duration;fighter.airSteerSpeed=arcSpeed;
  }

  function applyAirArcSteering(fighter,dt) {
    const arc=fighter.airDashArc,tuning=fighter.data.airDashArc,gravity=gravityVector(),right={x:gravity.y,y:-gravity.x};
    arc.age=Math.min(arc.duration,arc.age+dt);
    const aim=fighter.hasLiveAim&&length(fighter.aim)>0 ? normalize(fighter.aim) : null;
    if(tuning.freeSteering){
      if(aim){
        const delta=Math.atan2(Math.sin(Math.atan2(aim.y,aim.x)-arc.angle),Math.cos(Math.atan2(aim.y,aim.x)-arc.angle));
        arc.angle+=clamp(delta*(1-Math.exp(-tuning.steeringResponse*dt)),-tuning.maxTurnRate*dt,tuning.maxTurnRate*dt);
      }
      const decay=Math.pow(DASH_CARRY_AIR_DRAG,arc.age*60/tuning.durationScale);
      const magnitude=lerp(Math.hypot(fighter.vx,fighter.vy),arc.cruiseSpeed*decay,1-Math.exp(-tuning.velocityResponse*dt));
      fighter.vx=Math.cos(arc.angle)*magnitude;fighter.vy=Math.sin(arc.angle)*magnitude;
      fighter.airSteerTimer=Math.max(0,arc.duration-arc.age);if(arc.age>=arc.duration)delete fighter.airDashArc;
      return;
    }
    const input=aim ? clamp(-dot(aim,gravity),-1,1) : 0;
    const rise=input>0?lerp(tuning.neutralRise,tuning.highRise,input):lerp(tuning.neutralRise,tuning.lowRise,-input);
    const shapeBlend=1-Math.exp(-tuning.shapeResponse*dt),velocityBlend=1-Math.exp(-tuning.velocityResponse*dt);
    arc.rise=lerp(arc.rise,rise,shapeBlend);
    arc.phaseBias=lerp(arc.phaseBias,input>0?-input*tuning.upPhaseBias:-input*tuning.downPhaseBias,shapeBlend);
    if(aim&&Math.abs(dot(aim,right))>.18)arc.heading=lerp(arc.heading,dot(aim,right),1-Math.exp(-tuning.horizontalResponse*dt));
    const decay=Math.pow(DASH_CARRY_AIR_DRAG,arc.age*60/tuning.durationScale);
    const tangent=lerp(dot({x:fighter.vx,y:fighter.vy},right),arc.speed*arc.heading*decay,velocityBlend);
    const vertical=lerp(dot({x:fighter.vx,y:fighter.vy},gravity),arc.speed*arc.rise*(2*arc.age/arc.duration-1+2*arc.phaseBias),velocityBlend);
    fighter.vx=right.x*tangent+gravity.x*vertical;fighter.vy=right.y*tangent+gravity.y*vertical;
    fighter.airSteerTimer=Math.max(0,arc.duration-arc.age);
    if(arc.age>=arc.duration)delete fighter.airDashArc;
  }

  function applyAirDashSteering(fighter, dt) {
    if(fighter.airDashArc) {
      if(isAirArcActive(fighter)){applyAirArcSteering(fighter,dt);return;}
      delete fighter.airDashArc;
    }
    if (fighter.punchBlockstun > 0) return;
    if (fighter.airSteerTimer <= 0) {
      return;
    }

    if (fighter.onGround || fighter.wallSliding || fighter.hitstun > 0 || fighter.hitstop > 0) {
      fighter.airSteerTimer = 0;
      fighter.airSteerDuration = 0;
      fighter.airSteerSpeed = 0;
      return;
    }

    fighter.airSteerTimer = Math.max(0, fighter.airSteerTimer - dt);
    if (!fighter.hasLiveAim) {
      return;
    }

    const aim = length(fighter.aim) > 0 ? normalize(fighter.aim) : { ...fighter.face };
    const currentSpeed = length({ x: fighter.vx, y: fighter.vy });
    const velocityDir = currentSpeed > 1 ? normalize({ x: fighter.vx, y: fighter.vy }) : aim;
    const duration = fighter.airSteerDuration || fighter.data.airSteerDuration;
    const remaining = duration > 0 ? fighter.airSteerTimer / duration : 0;
    const controlFalloff = 0.45 + remaining * 0.55;
    const speedControl = getSpeedControl(currentSpeed);
    const opposing = dot(aim, velocityDir) < OPPOSITE_BRAKE_DOT;
    const accel = fighter.data.airSteerAccel * controlFalloff * (opposing ? Math.max(speedControl, 0.48) : speedControl)*fighterStatusScale(fighter,"movement");

    if (opposing) {
      const brake = Math.pow(AIR_STEER_BRAKE, dt * 60 * (1.1 - speedControl * 0.45));
      fighter.vx *= brake;
      fighter.vy *= brake;
    }

    fighter.vx += aim.x * accel * dt;
    fighter.vy += aim.y * accel * dt;

    const maxSpeed = Math.max(fighter.airSteerSpeed, currentSpeed * 0.96) * fighter.data.airSteerMaxSpeedScale;
    const steeredSpeed = length({ x: fighter.vx, y: fighter.vy });
    if (steeredSpeed > maxSpeed) {
      const scale = maxSpeed / steeredSpeed;
      fighter.vx *= scale;
      fighter.vy *= scale;
    }
  }

  function resetGroundRun(fighter,clearCarry=false){
    delete fighter.groundRun;
    if(clearCarry)delete fighter.runJumpCarry;
  }

  function isGroundRunning(fighter){
    return fighter.onGround&&(fighter.groundRun?.time||0)>=GROUND_RUN_DELAY-1e-9;
  }

  function groundRunSpeed(fighter,movement=1){
    return Math.min(GROUND_WALK_SPEED*(fighter.data.walkSpeedScale??1)*movement*GROUND_RUN_SPEED_SCALE,
      getDashSpeed(fighter,0,false)*GROUND_RUN_DASH_CAP);
  }

  function applyGroundWalk(fighter, dt) {
    if (
      !fighter.onGround ||
      !fighter.hasLiveAim ||
      fighter.crouching ||
      fighter.dashPending ||
      fighter.chargingDash ||
      fighter.attack&&!fighter.data.spear ||
      fighter.punchBlockstun > 0 ||
      fighter.hitstun > 0 ||
      fighter.hitstop > 0
    ) {
      resetGroundRun(fighter,!fighter.onGround||fighter.crouching||fighter.hitstun>0||fighter.hitstop>0||fighter.juked>0);
      return;
    }

    const aim = stageGravityAxis === "x" ? fighter.aim.y : fighter.aim.x;
    const movement=fighterStatusScale(fighter,"movement")*(isShielding(fighter)?fighter.data.shieldWalkScale??1:1)*(fighter.attack&&fighter.data.spear?fighter.data.spear.walk:1)*
      (dashballState?.sticky&&dashballState.ball.carrier===fighter.id ? .5 : 1);
    const current=stageGravityAxis==="x"?fighter.vy:fighter.vx;
    const icy=iceUnderFighter(fighter);
    const walkSpeed=GROUND_WALK_SPEED*(fighter.data.walkSpeedScale??1)*movement;
    if(Math.abs(current)<=walkSpeed||current*aim<0)delete fighter.runJumpCarry;
    const runnable=Math.abs(aim)>.18&&Math.abs(dot(fighter.aim,gravityVector()))<TIPPY_TOES_INPUT_DOT&&
      !fighter.attack&&!fighter.punchPending&&!fighter.chargingPunch&&!fighter.tippyToes&&fighter.groundSkidTimer<=0&&
      !fighter.heavyDashWindup&&!(fighter.heavyDashRecovery>0)&&fighter.juked<=0&&fighter.spotDodgeRecovery<=0&&fighter.surfaceTechTravelTimer<=0;
    if(runnable){
      const direction=Math.sign(aim),previous=fighter.groundRun;
      if(!previous||previous.direction!==direction||previous.axis!==stageGravityAxis||previous.sign!==stageGravitySign){
        fighter.groundRun={time:0,direction,axis:stageGravityAxis,sign:stageGravitySign};
      }
      const time=fighter.groundRun.time+dt,maximum=GROUND_RUN_DELAY+GROUND_RUN_ACCEL_TIME;
      fighter.groundRun.time=time>=maximum-1e-9?maximum:time;
    }else resetGroundRun(fighter);
    const progress=clamp(((fighter.groundRun?.time||0)-GROUND_RUN_DELAY)/GROUND_RUN_ACCEL_TIME,0,1);
    const target=Math.abs(aim)>.18?aim*lerp(walkSpeed,groundRunSpeed(fighter,movement),progress):0;
    // A committed heavy glide should not be canceled by walking the same way.
    if(fighter.data.groundDashSkidTime&&fighter.groundSkidTimer>0&&current*target>0&&Math.abs(current)>Math.abs(target))return;
    if((fighter.data.momentumWalk||icy)&&current*target>0&&Math.abs(current)>Math.abs(target))return;
    const reversing=current*target<0?(fighter.data.walkReverseScale??1):1;
    const accel = (Math.abs(target) > 0 ? GROUND_WALK_ACCEL*(fighter.data.walkAccelScale??1)*reversing*movement : GROUND_WALK_DECEL*(fighter.data.walkDecelScale??1))*(icy&&(current*target<=0)?Ice.TUNING.traction:1);
    if (stageGravityAxis === "x") fighter.vy = approach(fighter.vy, target, accel * dt);
    else fighter.vx = approach(fighter.vx, target, accel * dt);
    if(isGroundRunning(fighter))fighter.runJumpCarry=true;
  }

  function applyCrouchBrake(fighter, dt) {
    if (!fighter.onGround || !fighter.crouching || fighter.hitstun > 0) {
      return;
    }

    resetGroundRun(fighter,true);
    if (stageGravityAxis === "x") fighter.vy = 0;
    else fighter.vx = 0;
  }

  function updateAirFloatMomentumSource(fighter){
    if(!fighter.data.airFloat?.dashDrag)return;
    if(fighter.hitstun>0||fighter.juked>0||fighter.punchBlockstun>0||fighter.koScored||
       fighter.dashReboundFlash>0||fighter.mutualDashReboundFlash>0||fighter.clashLostTimer>0){
      fighter.floatMotion="external";
    }else if(fighter.onGround||fighter.wallSliding)delete fighter.floatMotion;
  }

  function applyAirFloatDashDrag(fighter,dt){
    const tuning=fighter.data.airFloat;
    if(!tuning?.dashDrag||fighter.floatMotion!=="self"||!canControlAirFloat(fighter)||isAirDashCharging(fighter))return;
    const gravity=gravityVector(),tangent={x:gravity.y,y:-gravity.x},decay=Math.exp(-tuning.dashDrag*dt);
    const side=dot({x:fighter.vx,y:fighter.vy},tangent)*decay;
    const falling=dot({x:fighter.vx,y:fighter.vy},gravity);
    const fall=falling<0?falling*decay:falling;
    fighter.vx=tangent.x*side+gravity.x*fall;fighter.vy=tangent.y*side+gravity.y*fall;
  }

  function canControlAirFloat(fighter) {
    return !fighter.onGround && !fighter.wallSliding && !fighter.koScored && fighter.health > 0 &&
      fighter.floatMotion!=="external" &&
      fighter.hitstun <= 0 && fighter.hitstop <= 0 && fighter.punchBlockstun <= 0 &&
      !fighter.shieldPressureRearm && fighter.juked <= 0 && fighter.spotDodgeRecovery <= 0 &&
      fighter.spotDodgeInvuln <= 0 && fighter.surfaceTechTravelTimer <= 0;
  }

  function getAirFloatUpInput(fighter) {
    if (!canControlAirFloat(fighter) || !fighter.hasLiveAim || length(fighter.aim) <= 0) return 0;
    return clamp(-dot(normalize(fighter.aim), gravityVector()), 0, 1);
  }

  function applyAirFloatControl(fighter, dt) {
    const tuning = fighter.data.airFloat;
    if (!tuning || !canControlAirFloat(fighter) || isAirDashCharging(fighter) ||
        fighter.airSteerTimer > 0 || fighter.dashCarryTimer > 0) return;

    const gravity = gravityVector(), tangent = { x: gravity.y, y: -gravity.x };
    const aim = fighter.hasLiveAim && length(fighter.aim) > 0 ? normalize(fighter.aim) : { x: 0, y: 0 };
    const input = dot(aim, tangent);
    const side = approach(fighter.vx * tangent.x + fighter.vy * tangent.y,
      input * tuning.moveSpeed*fighterStatusScale(fighter,"movement"), (Math.abs(input) > 0.18 ? tuning.accel*fighterStatusScale(fighter,"movement") : tuning.brake) * dt);
    let fall = fighter.vx * gravity.x + fighter.vy * gravity.y;
    const cap = lerp(tuning.maxFallSpeed, tuning.upFallSpeed, getAirFloatUpInput(fighter));
    // Only brake descent: air-walking must not erase upward dashes or add lift.
    if (fall > cap) fall = approach(fall, cap, tuning.fallBrake * dt);
    fighter.vx = tangent.x * side + gravity.x * fall;
    fighter.vy = tangent.y * side + gravity.y * fall;
  }

  function applyFreeFallControl(fighter, dt) {
    if (fighter.data.airFloat) return;
    if (fighter.punchBlockstun > 0) return;
    if (
      fighter.onGround ||
      fighter.wallSliding ||
      fighter.hitstun > 0 ||
      fighter.hitstop > 0 ||
      fighter.chargingDash ||
      fighter.airBrakeOnly ||
      fighter.airSteerTimer > 0 ||
      fighter.airDashes > 0 ||
      !fighter.hasLiveAim
    ) {
      return;
    }

    const aim = length(fighter.aim) > 0 ? normalize(fighter.aim) : { ...fighter.face };
    const speed = length({ x: fighter.vx, y: fighter.vy });
    const control = getSpeedControl(speed);
    const velocityDir = speed > 1 ? normalize({ x: fighter.vx, y: fighter.vy }) : aim;
    const opposing = dot(aim, velocityDir) < OPPOSITE_BRAKE_DOT;

    if (opposing) {
      const brake = Math.pow(FREEFALL_BRAKE, dt * 60 * (1.15 - control * 0.35));
      fighter.vx *= brake;
      fighter.vy *= brake;
    }

    fighter.vx += aim.x * FREEFALL_CONTROL_ACCEL * control * dt*(fighter.data.freeFallControlScale??1)*fighterStatusScale(fighter,"movement");
    fighter.vy += aim.y * FREEFALL_CONTROL_ACCEL * control * 0.82 * dt*(fighter.data.freeFallControlScale??1)*fighterStatusScale(fighter,"movement");
  }

  function applyHitstunDI(fighter, dt) {
    if (fighter.hitstun <= 0 || !fighter.hasLiveAim) {
      return;
    }

    const aim = length(fighter.aim) > 0 ? normalize(fighter.aim) : { ...fighter.lastHitDir };
    const speed = length({ x: fighter.vx, y: fighter.vy });
    const reboundT = clamp(fighter.dashReboundDITimer / DASH_REBOUND_DI_TIME, 0, 1);
    const speedControl =
      reboundT > 0 ? Math.max(getSpeedControl(speed), DASH_REBOUND_DI_MIN_SPEED_CONTROL) : getSpeedControl(speed);
    const reboundBoost = reboundT > 0 ? lerp(1, DASH_REBOUND_DI_MULT, reboundT) : 1;
    const comboDiBoost = 1 + Math.min(
      Math.max(0, fighter.comboHits - 1) * COMBO_DI_PER_EXTRA_HIT,
      COMBO_DI_MAX_BONUS,
    );
    const control = speedControl * HITSTUN_DI_MAX_SCALE * fighter.data.comboDIStrength * reboundBoost * comboDiBoost;
    fighter.vx += aim.x * HITSTUN_DI_ACCEL * control * dt;
    fighter.vy += aim.y * HITSTUN_DI_ACCEL * control * dt;
  }

  function getSpeedControl(speed) {
    const t = clamp((speed - CONTROL_LOW_SPEED) / (CONTROL_HIGH_SPEED - CONTROL_LOW_SPEED), 0, 1);
    return lerp(1, HIGH_SPEED_MIN_CONTROL, easeOutQuad(t));
  }

  function beginPunchAim(fighter, direction) {
    const dir = length(direction) > 0 ? normalize(direction) : { ...fighter.face };
    fighter.punchAim = dir;
    fighter.punchAimSamples = [];
  }

  function updatePunchAim(fighter, direction, hasAim, dt) {
    for (const sample of fighter.punchAimSamples) {
      sample.age += dt;
    }
    fighter.punchAimSamples = fighter.punchAimSamples.filter(
      (sample) => sample.age <= PUNCH_AIM_SAMPLE_WINDOW,
    );

    if (hasAim && length(direction) > 0) {
      fighter.punchAimSamples.push({ dir: normalize(direction), age: 0 });
    }
    if (fighter.punchAimSamples.length === 0) {
      return fighter.punchAim;
    }

    let x = 0;
    let y = 0;
    let totalWeight = 0;
    for (const sample of fighter.punchAimSamples) {
      const recency = 1 - clamp(sample.age / PUNCH_AIM_SAMPLE_WINDOW, 0, 1);
      const weight = lerp(0.7, 1.35, recency);
      x += sample.dir.x * weight;
      y += sample.dir.y * weight;
      totalWeight += weight;
    }

    const averaged = { x: x / totalWeight, y: y / totalWeight };
    if (length(averaged) > 0.12) {
      fighter.punchAim = normalize(averaged);
    } else {
      fighter.punchAim = { ...fighter.punchAimSamples[fighter.punchAimSamples.length - 1].dir };
    }
    return fighter.punchAim;
  }

  function releasePunch(fighter, direction, chargeTime) {
    if((dashballState||sandbagState)&&fighter.dashballSpawnProtected){fighter.invulnerable=0;delete fighter.dashballSpawnProtected;}
    if (fighter.punchBlockstun > 0 || fighter.shieldPressureRearm) return;
    if(fighter.data.boomerang&&(hasActiveBoomerang(fighter)||fighter.boomerangRecallRelease)){
      fighter.boomerangRecallRelease=false;
      const shield=isShielding(fighter);
      fighter.punchPending=false;fighter.punchReleaseQueued=false;fighter.chargingPunch=false;fighter.punchCharge=0;fighter.punchHoldTimer=0;fighter.punchAimSamples=[];
      if(shield){fighter.shieldReleaseParry=SHIELD_RELEASE_PARRY_WINDOW;fighter.shieldReleaseWhiffFlash=SHIELD_RELEASE_WHIFF_FLASH_TIME;}
      return;
    }
    if (fighter.data.maxPunches && fighter.punches <= 0) {
      fighter.punchPending = false;
      fighter.punchReleaseQueued = false;
      fighter.chargingPunch = false;
      fighter.punchHoldTimer = 0;
      fighter.punchCharge = 0;
      fighter.punchAimSamples = [];
      sparkText(fighter.x, fighter.y - 58, "LAND TO RELOAD", fighter.data.lightColor);
      return;
    }
    if (fighter.data.maxPunches) fighter.punches -= 1;
    const data = fighter.data;
    const releasedShield = isShielding(fighter);
    fighter.punchReleaseQueued = false;
    const charge = fighter.punchExhausted ? 0 : clamp(chargeTime / data.punchChargeTime, 0, 1);
    const dir = length(direction) > 0 ? normalize(direction) : { ...fighter.face };
    const active = data.punchActive + charge * (data.punchChargeActive??0.22);
    const recovery = data.noWhiffPenalty ? 0 : data.punchRecoveryCharge===undefined?data.punchRecovery*(1+charge*.22):data.punchRecovery+data.punchRecoveryCharge*charge*charge;
    const startup = data.punchStartup + (data.punchStartupCharge||0)*charge + (releasedShield ? SHIELD_RELEASE_EXTRA_STARTUP : 0);

    fighter.attack = {
      id: ++attackSerial,
      age: 0,
      startup,
      active,
      recovery,
      total: startup + active + recovery,
      dir,
      charge,
      hitTargets: new Set(),
      clashed: false,
      selfCancelled: false,
      fromShieldRelease: releasedShield,
      shieldParryTriggered: false,
      grounded: fighter.onGround,
      ...(data.projectilePunch && !(fighter.reloadRemaining>0) ? { projectile: {
        x: fighter.x, y: fighter.y,
        speed: data.projectileConfig ? data.projectileConfig.speed + charge * data.projectileConfig.chargeSpeed : (1050 + charge * 450) * (data.projectileSpeedMult || 1),
        radius: data.projectileConfig ? data.projectileConfig.radius + charge * data.projectileConfig.chargeRadius : data.arrowPunch ? 4 + charge * 3 : 8 + charge * 7, spawned: false,
        arrow: Boolean(data.arrowPunch),
        damage: data.punchDamage, knockback: data.punchKnockback, hitstun: data.projectileConfig?.hitstun??data.punchHitstun,
        ...(data.projectileConfig ? { persistent: true, remainingLife: data.projectileConfig.life,
          pressure:true,maxHitstun:data.projectileConfig.maxHitstun,hitstop:data.projectileConfig.hitstop,
          blockstun:data.projectileConfig.blockstun,chargeBlockstun:data.projectileConfig.chargeBlockstun,shieldDamageScale:data.projectileConfig.shieldDamageScale,
          maxSpeed: data.projectileConfig.maxSpeed, mass: data.projectileConfig.mass, terrainBounce: data.projectileConfig.terrainBounce } : {}),
      } } : {}),
    };
    if(data.spear){
      fighter.attack.active=lerp(...data.spear.extension,charge)+lerp(...data.spear.hold,charge);
      fighter.attack.total=startup+fighter.attack.active+recovery;
    }
    if(data.punchSequence){
      const stage=fighter.edgebertFollowup??0,profile=data.punchSequence[stage],timing=getSequenceTiming(profile,undefined,releasedShield);
      Object.assign(fighter.attack,{sequenceStage:stage,startup:timing.startup,active:timing.active,recovery:timing.recovery,total:timing.total});
      fighter.edgebertChain={stage,age:0,dir:{...dir},...timing};fighter.edgebertFollowup=null;
    }
    const actionSpeed=fighterStatusScale(fighter,"action");
    if(actionSpeed!==1){
      // Capture action timing once: expiration cannot jump an in-flight hitbox.
      fighter.attack.actionSpeed=actionSpeed;
      for(const key of["startup","active","recovery","total"])fighter.attack[key]/=actionSpeed;
      if(data.punchSequence)for(const key of["startup","active","recovery","total","cancelAt"])fighter.edgebertChain[key]/=actionSpeed;
    }
    fighter.punchPending = false;
    fighter.punchHoldTimer = 0;
    fighter.chargingPunch = false;
    fighter.punchCharge = 0;
    fighter.punchAimSamples = [];
    clearShieldDashLockout(fighter);
    fighter.shieldReleaseParry = releasedShield ? SHIELD_RELEASE_PARRY_WINDOW : 0;
    fighter.shieldFlash = Math.max(fighter.shieldFlash, releasedShield ? SHIELD_RELEASE_PARRY_WINDOW : 0);
    fighter.shieldReleaseWhiffFlash = releasedShield ? SHIELD_RELEASE_WHIFF_FLASH_TIME : 0;
    fighter.face = { ...dir };
    if (releasedShield) {
      playAudioEvent("shieldReleaseWhiff", { fighter, charge, intensity: 0.68 + charge * 0.22 });
    }
    if(!data.spear&&!fighter.attack.projectile)playAudioEvent("punchSwing", { fighter, charge, intensity: 0.55 + charge * 0.35 });
  }

  function getPunchProfile(fighter,attack=fighter.attack){
    if(attack?.materialization){const p=attack.materialization;return {...fighter.data,punchDamage:p.damage,punchKnockback:p.knockback,punchHitstun:p.hitstun};}
    if(fighter.data.spear&&attack){const p=SPEAR_ZONES[attack.spearZone||"haft"],charge=attack.charge||0;
      return {...fighter.data,punchDamage:lerp(...p.damage,charge),punchDamageCharge:0,punchKnockback:lerp(...p.knockback,charge),punchHitstun:p.hitstun};}
    return fighter.data.punchSequence?.[attack?.sequenceStage??fighter.edgebertFollowup??0]||fighter.data;
  }

  const SPEAR_ZONES=Object.freeze({tip:{damage:[25,100],knockback:[1100,2400],hitstun:.65},
    shaft:{damage:[4,12],knockback:[450,800],hitstun:.38},haft:{damage:[3,10],knockback:[100,180],hitstun:.22}});
  function spearExtension(t){
    t=clamp(t,0,1);const times=[0,.4,.7,1],values=[0,.15,.4,1],slopes=[0,.6,1.2,2.8];
    let i=t<.4?0:t<.7?1:2;const span=times[i+1]-times[i],u=(t-times[i])/span;
    return (2*u**3-3*u*u+1)*values[i]+(u**3-2*u*u+u)*span*slopes[i]+
      (-2*u**3+3*u*u)*values[i+1]+(u**3-u*u)*span*slopes[i+1];
  }
  function spearPose(fighter,age=fighter.attack?.age){
    const a=fighter.attack,t=fighter.data.spear;if(!a||!t)return null;
    const speed=a.actionSpeed||1,thrust=lerp(...t.extension,a.charge)/speed,hold=lerp(...t.hold,a.charge)/speed;
    const elapsed=age-a.startup,phase=elapsed<0?"windup":elapsed<thrust?"thrust":elapsed<thrust+hold?"hold":"retract";
    const extension=phase==="windup"?0:phase==="thrust"?spearExtension(elapsed/thrust):phase==="hold"?1:1-clamp((elapsed-thrust-hold)/a.recovery,0,1);
    const dir=normalize(a.dir),bodyReach=Math.abs(dir.x)*fighter.data.width/2+Math.abs(dir.y)*getBodyHeight(fighter)/2;
    const reach=t.reach+t.tip*.5*a.charge,length=reach*extension;
    return {phase,extension,bodyReach,reach,length,tip:t.tip*(1+.5*a.charge),halfWidth:t.halfWidth,dir,
      x:fighter.x+dir.x*bodyReach,y:fighter.y+dir.y*bodyReach,thrust,hold};
  }
  const SPEAR_SHAFT_HIT_SECONDS=.1;
  function spearShaftActive(fighter){
    const p=spearPose(fighter),a=fighter.attack;
    return Boolean(p&&a.age>=a.startup&&a.age-a.startup<=p.thrust+SPEAR_SHAFT_HIT_SECONDS/(a.actionSpeed||1)+1e-9);
  }
