    const along=dot(offset,p.dir)-p.bodyReach,oldAlong=dot(oldOffset,p.dir)-p.bodyReach,across=dot(offset,normal),oldAcross=dot(oldOffset,normal);
    const w=kind==="fighter"?object.data.width:object.w,h=kind==="fighter"?getBodyHeight(object):object.h;
    const extent=object.r??(Math.abs(normal.x)*w+Math.abs(normal.y)*h)/2,axial=object.r??(Math.abs(p.dir.x)*w+Math.abs(p.dir.y)*h)/2;
