      const terrainList=(dashballState?.targets?currentStage().terrain.concat(dashballState.targets.filter(t=>!t.destroyed).map(t=>({x:t.x-t.r,y:t.y-t.r,w:t.r*2,h:t.r*2,kind:"wall",target:t}))):currentStage().terrain).concat(boulderTerrain(fighter,previousGroundId),spearTerrain(fighter));
