    const weaponHeld=Boolean(fighter.data.spear&&(fighter.attack||fighter.chargingPunch||!fighter.koScored&&effects.some(e=>e.spearWithdraw===fighter.id&&e.life>0)));
    sheet = getCharacterSpriteSheet(sheet,clip,set,fighter.data,{weaponHeld});
    const auraHead=fighter.data===CHARACTER_DATA.microusb||fighter.data===CHARACTER_DATA.icer||fighter.data===CHARACTER_DATA.ember?sheet.characterDetail?.frames[clip.images?0:animation.frame]?.head:null;
