      rect("#282638",cx+Math.max(1,Math.floor(r*.5))-1,mid-Math.max(2,Math.floor(r*.3)),2,2);
      const mouth=Math.max(2,Math.floor(r*.55));
      for(let x=-mouth;x<=mouth;x++)rect("#393047",cx+x,mid+Math.floor(r*.24)+Math.round((x/mouth)**2*r*.3),1,1);
      for(let x=0;x<cx-r;x+=3)rect("#77718f",x,mid,2,1);
