    // Bake rotation by nearest-neighbor sampling; Canvas rotation would soften native pixels.
    const size=Math.ceil(Math.hypot(w,h))+2,frame=document.createElement("canvas");frame.width=frame.height=size;
    const source=c.getImageData(0,0,w,h).data,target=frame.getContext("2d"),output=target.createImageData(size,size);
    const theta=angle*Math.PI*2/128,cos=Math.cos(theta),sin=Math.sin(theta);
