  window.addEventListener("focus",()=>{menuBackFocusLost=false;});
  document.addEventListener?.("visibilitychange",()=>{if(document.hidden){menuBackKeys.clear();menuBackHolds.cancel();pollMenuBackHolds(performance.now(),getGamepads(),true);}});
  window.addEventListener("beforeunload", () => closeOnlineConnections(true));

